        db.executescript(
            """
            CREATE TABLE IF NOT EXISTS tender_requirement_documents (
                requirement_id INTEGER NOT NULL REFERENCES tender_document_requirements(id) ON DELETE CASCADE,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                document_id INTEGER NOT NULL REFERENCES company_tender_documents(id) ON DELETE CASCADE,
                sort_order INTEGER NOT NULL DEFAULT 0,
                created_at TEXT NOT NULL,
                PRIMARY KEY(requirement_id,document_id)
            );
            CREATE INDEX IF NOT EXISTS idx_tender_requirement_documents_company
              ON tender_requirement_documents(company_id,requirement_id,sort_order);
            CREATE TABLE IF NOT EXISTS notification_alerts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                alert_key TEXT NOT NULL,
                notification_id INTEGER NOT NULL REFERENCES notifications(id) ON DELETE CASCADE,
                entity_type TEXT NOT NULL,
                entity_id INTEGER NOT NULL,
                due_date TEXT,
                created_at TEXT NOT NULL,
                UNIQUE(company_id,alert_key)
            );
            CREATE INDEX IF NOT EXISTS idx_notification_alerts_entity
              ON notification_alerts(company_id,entity_type,entity_id);
            CREATE TABLE IF NOT EXISTS notification_preferences (
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
                categories_json TEXT NOT NULL DEFAULT '{}',
                minimum_level TEXT NOT NULL DEFAULT 'info',
                daily_email INTEGER NOT NULL DEFAULT 0,
                critical_email INTEGER NOT NULL DEFAULT 1,
                quiet_hours_json TEXT NOT NULL DEFAULT '{}',
                daily_digest_hour INTEGER NOT NULL DEFAULT 8,
                updated_at TEXT NOT NULL,
                PRIMARY KEY(company_id,user_id)
            );
            CREATE TABLE IF NOT EXISTS notification_email_deliveries (
                notification_id INTEGER NOT NULL REFERENCES notifications(id) ON DELETE CASCADE,
                user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
                delivery_kind TEXT NOT NULL,
                delivered_at TEXT NOT NULL,
                PRIMARY KEY(notification_id,user_id,delivery_kind)
            );
            CREATE TABLE IF NOT EXISTS notification_email_digests (
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
                digest_date TEXT NOT NULL,
                item_count INTEGER NOT NULL,
                delivered_at TEXT NOT NULL,
                PRIMARY KEY(company_id,user_id,digest_date)
            );

            CREATE TABLE IF NOT EXISTS tender_proposals (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                tender_result_id INTEGER NOT NULL REFERENCES tender_results(id) ON DELETE CASCADE,
                status TEXT NOT NULL DEFAULT 'DRAFT'
                  CHECK(status IN ('DRAFT','PENDING_APPROVAL','APPROVED','REJECTED')),
                current_version INTEGER NOT NULL DEFAULT 0 CHECK(current_version >= 0),
                submitted_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                submitted_at TEXT,
                decided_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                decided_at TEXT,
                decision_comment TEXT,
                created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                updated_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                UNIQUE(company_id,tender_result_id)
            );
            CREATE INDEX IF NOT EXISTS idx_tender_proposals_status
              ON tender_proposals(company_id,status,updated_at);
            CREATE TABLE IF NOT EXISTS tender_proposal_versions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                proposal_id INTEGER NOT NULL REFERENCES tender_proposals(id) ON DELETE CASCADE,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                version INTEGER NOT NULL CHECK(version > 0),
                commercial_json TEXT NOT NULL DEFAULT '{}',
                total_cost_cents INTEGER NOT NULL DEFAULT 0 CHECK(total_cost_cents >= 0),
                total_price_cents INTEGER NOT NULL DEFAULT 0 CHECK(total_price_cents >= 0),
                margin_cents INTEGER NOT NULL DEFAULT 0,
                margin_bps INTEGER,
                created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                created_at TEXT NOT NULL,
                UNIQUE(proposal_id,version)
            );
            CREATE INDEX IF NOT EXISTS idx_tender_proposal_versions_company
              ON tender_proposal_versions(company_id,proposal_id,version DESC);
            CREATE TABLE IF NOT EXISTS tender_proposal_version_items (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                version_id INTEGER NOT NULL REFERENCES tender_proposal_versions(id) ON DELETE CASCADE,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                sort_order INTEGER NOT NULL DEFAULT 0,
                source_kind TEXT NOT NULL DEFAULT 'MANUAL'
                  CHECK(source_kind IN ('PNCP','AI_REVIEW_REQUIRED','MANUAL')),
                source_item_number TEXT,
                source_reference TEXT NOT NULL,
                catalog_record_id INTEGER REFERENCES records(id) ON DELETE RESTRICT,
                catalog_module TEXT CHECK(
                  catalog_module IS NULL OR catalog_module IN ('produtos','catalogo_servicos')
                ),
                catalog_code TEXT,
                catalog_cost_cents INTEGER CHECK(
                  catalog_cost_cents IS NULL OR catalog_cost_cents >= 0
                ),
                cost_source TEXT NOT NULL DEFAULT 'MANUAL_VALIDATED' CHECK(
                  cost_source IN ('INVENTORY_AVERAGE','CATALOG_REFERENCE','MANUAL_VALIDATED')
                ),
                available_quantity_micros INTEGER CHECK(
                  available_quantity_micros IS NULL OR available_quantity_micros >= 0
                ),
                supply_mode TEXT NOT NULL DEFAULT 'UNDEFINED' CHECK(
                  supply_mode IN ('UNDEFINED','STOCK','PURCHASE','MANUFACTURE','MIXED',
                                  'SERVICE_CAPACITY','EXCEPTION')
                ),
                supply_notes TEXT,
                catalog_exception_reason TEXT,
                description TEXT NOT NULL,
                unit TEXT NOT NULL,
                quantity_micros INTEGER NOT NULL CHECK(quantity_micros > 0),
                reference_price_cents INTEGER CHECK(reference_price_cents IS NULL OR reference_price_cents >= 0),
                unit_cost_cents INTEGER NOT NULL CHECK(unit_cost_cents >= 0),
                minimum_unit_price_cents INTEGER NOT NULL CHECK(minimum_unit_price_cents >= 0),
                unit_price_cents INTEGER NOT NULL CHECK(unit_price_cents >= 0),
                line_cost_cents INTEGER NOT NULL CHECK(line_cost_cents >= 0),
                line_total_cents INTEGER NOT NULL CHECK(line_total_cents >= 0)
            );
            CREATE INDEX IF NOT EXISTS idx_tender_proposal_items_version
              ON tender_proposal_version_items(company_id,version_id,sort_order,id);
            CREATE TABLE IF NOT EXISTS tender_proposal_decisions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                proposal_id INTEGER NOT NULL REFERENCES tender_proposals(id) ON DELETE CASCADE,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                version INTEGER NOT NULL CHECK(version > 0),
                action TEXT NOT NULL
                  CHECK(action IN ('SUBMITTED','APPROVED','REJECTED','WITHDRAWN','REOPENED')),
                actor_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
                comment TEXT,
                created_at TEXT NOT NULL
            );
            CREATE INDEX IF NOT EXISTS idx_tender_proposal_decisions_history
              ON tender_proposal_decisions(company_id,proposal_id,id DESC);

            CREATE TABLE IF NOT EXISTS tender_agent_policies (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                tender_result_id INTEGER NOT NULL REFERENCES tender_results(id) ON DELETE CASCADE,
                proposal_id INTEGER NOT NULL REFERENCES tender_proposals(id) ON DELETE RESTRICT,
                proposal_version_id INTEGER NOT NULL
                  REFERENCES tender_proposal_versions(id) ON DELETE RESTRICT,
                proposal_version INTEGER NOT NULL CHECK(proposal_version > 0),
                portal_key TEXT NOT NULL DEFAULT 'PNCP_REFERENCE'
                  CHECK(portal_key IN ('COMPRAS_GOV','PNCP_REFERENCE','LICITANET','BLL')),
                portal_url TEXT,
                mode TEXT NOT NULL DEFAULT 'SHADOW'
                  CHECK(mode IN ('SHADOW','SUPERVISED','AUTONOMOUS')),
                status TEXT NOT NULL DEFAULT 'PREPARED'
                  CHECK(status IN ('PREPARED','ARMED','PAUSED','CLOSED')),
                approved_total_cents INTEGER NOT NULL CHECK(approved_total_cents > 0),
                floor_total_cents INTEGER NOT NULL CHECK(
                  floor_total_cents > 0 AND floor_total_cents <= approved_total_cents
                ),
                minimum_step_cents INTEGER NOT NULL DEFAULT 100 CHECK(minimum_step_cents > 0),
                maximum_reduction_cents INTEGER NOT NULL DEFAULT 50000
                  CHECK(maximum_reduction_cents > 0),
                maximum_bid_count INTEGER NOT NULL DEFAULT 100
                  CHECK(maximum_bid_count BETWEEN 1 AND 1000),
                valid_from TEXT,
                valid_until TEXT,
                allow_proposal_submission INTEGER NOT NULL DEFAULT 0 CHECK(allow_proposal_submission IN (0,1)),
                allow_live_bidding INTEGER NOT NULL DEFAULT 0 CHECK(allow_live_bidding IN (0,1)),
                written_authorization_reference TEXT,
                revision INTEGER NOT NULL DEFAULT 1 CHECK(revision > 0),
                created_by INTEGER REFERENCES users(id),
                approved_by INTEGER REFERENCES users(id),
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                UNIQUE(company_id,tender_result_id,proposal_version)
            );
            CREATE INDEX IF NOT EXISTS idx_tender_agent_policy_status
              ON tender_agent_policies(company_id,status,valid_until);
            CREATE TABLE IF NOT EXISTS tender_agent_runs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                policy_id INTEGER NOT NULL REFERENCES tender_agent_policies(id) ON DELETE RESTRICT,
                status TEXT NOT NULL DEFAULT 'QUEUED'
                  CHECK(status IN ('QUEUED','RUNNING','AWAITING_MANUAL','COMPLETED','FAILED','CANCELLED')),
                adapter TEXT NOT NULL DEFAULT 'BROWSER_PROTOCOL',
                last_market_value_cents INTEGER,
                last_own_bid_cents INTEGER,
                authorized_bid_count INTEGER NOT NULL DEFAULT 0 CHECK(authorized_bid_count >= 0),
                last_heartbeat_at TEXT,
                last_error TEXT,
                started_by INTEGER REFERENCES users(id),
                started_at TEXT,
                finished_at TEXT,
                created_at TEXT NOT NULL
            );
            CREATE INDEX IF NOT EXISTS idx_tender_agent_run_policy
              ON tender_agent_runs(company_id,policy_id,id DESC);
            CREATE TABLE IF NOT EXISTS tender_agent_commands (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                run_id INTEGER NOT NULL REFERENCES tender_agent_runs(id) ON DELETE CASCADE,
                sequence INTEGER NOT NULL CHECK(sequence > 0),
                action TEXT NOT NULL CHECK(action IN (
                  'NAVIGATE','VERIFY_CONTEXT','PREPARE_PROPOSAL','SUBMIT_PROPOSAL',
                  'MONITOR_SESSION','PLACE_BID','CAPTURE_RECEIPT','HALT'
                )),
                state TEXT NOT NULL DEFAULT 'QUEUED' CHECK(state IN (
                  'QUEUED','LEASED','COMPLETED','FAILED','MANUAL_REQUIRED','CANCELLED'
                )),
                requested_value_cents INTEGER,
                authorized_value_cents INTEGER,
                payload_json TEXT NOT NULL DEFAULT '{}',
                idempotency_key TEXT NOT NULL,
                lease_owner TEXT,
                lease_until TEXT,
                attempt_count INTEGER NOT NULL DEFAULT 0 CHECK(attempt_count >= 0),
                created_at TEXT NOT NULL,
                completed_at TEXT,
                UNIQUE(company_id,idempotency_key),
                UNIQUE(run_id,sequence)
            );
            CREATE INDEX IF NOT EXISTS idx_tender_agent_command_queue
              ON tender_agent_commands(company_id,state,id);
            CREATE TABLE IF NOT EXISTS tender_agent_receipts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                run_id INTEGER NOT NULL REFERENCES tender_agent_runs(id) ON DELETE RESTRICT,
                command_id INTEGER REFERENCES tender_agent_commands(id) ON DELETE RESTRICT,
                event_type TEXT NOT NULL,
                external_effect INTEGER NOT NULL DEFAULT 0 CHECK(external_effect IN (0,1)),
                success INTEGER NOT NULL CHECK(success IN (0,1)),
                portal_protocol TEXT,
                evidence_sha256 TEXT,
                detail_json TEXT NOT NULL DEFAULT '{}',
                created_at TEXT NOT NULL
            );
            CREATE INDEX IF NOT EXISTS idx_tender_agent_receipt_run
              ON tender_agent_receipts(company_id,run_id,id DESC);

            CREATE TRIGGER IF NOT EXISTS trg_tender_agent_policy_scope_insert
            BEFORE INSERT ON tender_agent_policies
            WHEN NOT EXISTS (
              SELECT 1 FROM tender_results t
              JOIN tender_proposals p ON p.id=NEW.proposal_id
              JOIN tender_proposal_versions v ON v.id=NEW.proposal_version_id
              WHERE t.id=NEW.tender_result_id AND t.company_id=NEW.company_id
                AND p.tender_result_id=t.id AND p.company_id=NEW.company_id
                AND p.status='APPROVED' AND p.current_version=NEW.proposal_version
                AND v.proposal_id=p.id AND v.company_id=NEW.company_id
                AND v.version=NEW.proposal_version
            )
            BEGIN SELECT RAISE(ABORT,'agente fora da empresa ou proposta aprovada'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_agent_policy_scope_update
            BEFORE UPDATE OF company_id,tender_result_id,proposal_id,proposal_version_id,
                             proposal_version,approved_total_cents,floor_total_cents
            ON tender_agent_policies
            BEGIN SELECT RAISE(ABORT,'fotografia financeira do agente e imutavel'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_agent_run_scope_insert
            BEFORE INSERT ON tender_agent_runs
            WHEN COALESCE((SELECT company_id FROM tender_agent_policies WHERE id=NEW.policy_id),-1)
                 != NEW.company_id
            BEGIN SELECT RAISE(ABORT,'execucao do agente fora da empresa'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_agent_command_scope_insert
            BEFORE INSERT ON tender_agent_commands
            WHEN COALESCE((SELECT company_id FROM tender_agent_runs WHERE id=NEW.run_id),-1)
                 != NEW.company_id
            BEGIN SELECT RAISE(ABORT,'comando do agente fora da empresa'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_agent_command_core_update
            BEFORE UPDATE OF company_id,run_id,sequence,action,requested_value_cents,
                             authorized_value_cents,payload_json,idempotency_key,created_at
            ON tender_agent_commands
            BEGIN SELECT RAISE(ABORT,'conteudo autorizado do comando e imutavel'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_agent_receipt_scope_insert
            BEFORE INSERT ON tender_agent_receipts
            WHEN COALESCE((SELECT company_id FROM tender_agent_runs WHERE id=NEW.run_id),-1)
                 != NEW.company_id
              OR (NEW.command_id IS NOT NULL AND COALESCE((
                    SELECT company_id FROM tender_agent_commands
                    WHERE id=NEW.command_id AND run_id=NEW.run_id
                  ),-1) != NEW.company_id)
            BEGIN SELECT RAISE(ABORT,'recibo do agente fora da empresa'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_agent_receipt_immutable_update
            BEFORE UPDATE ON tender_agent_receipts
            BEGIN SELECT RAISE(ABORT,'recibo do agente e imutavel'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_agent_receipt_immutable_delete
            BEFORE DELETE ON tender_agent_receipts
            BEGIN SELECT RAISE(ABORT,'recibo do agente e imutavel'); END;

            CREATE TABLE IF NOT EXISTS tender_operational_handoffs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                tender_result_id INTEGER NOT NULL REFERENCES tender_results(id) ON DELETE RESTRICT,
                proposal_id INTEGER NOT NULL REFERENCES tender_proposals(id) ON DELETE RESTRICT,
                proposal_version_id INTEGER NOT NULL
                  REFERENCES tender_proposal_versions(id) ON DELETE RESTRICT,
                proposal_version INTEGER NOT NULL CHECK(proposal_version > 0),
                licitacao_record_id INTEGER NOT NULL REFERENCES records(id) ON DELETE RESTRICT,
                customer_record_id INTEGER NOT NULL REFERENCES records(id) ON DELETE RESTRICT,
                contract_record_id INTEGER NOT NULL REFERENCES records(id) ON DELETE RESTRICT,
                execution_record_id INTEGER NOT NULL REFERENCES records(id) ON DELETE RESTRICT,
                execution_module TEXT NOT NULL
                  CHECK(execution_module IN ('vendas','ordens_servico')),
                purchase_request_record_id INTEGER REFERENCES records(id) ON DELETE RESTRICT,
                status TEXT NOT NULL DEFAULT 'MATERIALIZED'
                  CHECK(status IN ('MATERIALIZED','CANCELLED')),
                created_by INTEGER REFERENCES users(id),
                created_at TEXT NOT NULL,
                UNIQUE(company_id,tender_result_id),
                UNIQUE(company_id,proposal_id,proposal_version)
            );
            CREATE INDEX IF NOT EXISTS idx_tender_handoffs_execution
              ON tender_operational_handoffs(company_id,execution_record_id);
            CREATE TRIGGER IF NOT EXISTS trg_tender_handoff_scope_insert
            BEFORE INSERT ON tender_operational_handoffs
            WHEN NOT EXISTS (
              SELECT 1 FROM tender_results t
              JOIN tender_proposals p ON p.id=NEW.proposal_id
              JOIN tender_proposal_versions v ON v.id=NEW.proposal_version_id
              WHERE t.id=NEW.tender_result_id AND t.company_id=NEW.company_id
                AND p.tender_result_id=t.id AND p.company_id=NEW.company_id
                AND v.proposal_id=p.id AND v.company_id=NEW.company_id
                AND v.version=NEW.proposal_version
            )
              OR COALESCE((SELECT company_id FROM records WHERE id=NEW.licitacao_record_id
                            AND module='licitacoes'),-1) != NEW.company_id
              OR COALESCE((SELECT company_id FROM records WHERE id=NEW.customer_record_id
                            AND module IN ('clientes','fornecedores')),-1) != NEW.company_id
              OR COALESCE((SELECT company_id FROM records WHERE id=NEW.contract_record_id
                            AND module='contratos'),-1) != NEW.company_id
              OR COALESCE((SELECT company_id FROM records WHERE id=NEW.execution_record_id
                            AND module=NEW.execution_module),-1) != NEW.company_id
              OR (NEW.purchase_request_record_id IS NOT NULL AND
                  COALESCE((SELECT company_id FROM records
                            WHERE id=NEW.purchase_request_record_id
                              AND module='solicitacoes_compra'),-1) != NEW.company_id)
            BEGIN SELECT RAISE(ABORT,'handoff operacional fora da empresa ou fluxo'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_handoff_immutable_update
            BEFORE UPDATE OF company_id,tender_result_id,proposal_id,proposal_version_id,
                             proposal_version,licitacao_record_id,customer_record_id,
                             contract_record_id,execution_record_id,execution_module,
                             purchase_request_record_id
            ON tender_operational_handoffs
            BEGIN SELECT RAISE(ABORT,'vínculos do handoff são imutáveis'); END;

            CREATE TRIGGER IF NOT EXISTS trg_tender_proposal_company_insert
            BEFORE INSERT ON tender_proposals
            WHEN NOT EXISTS (
              SELECT 1 FROM tender_results r
              WHERE r.id=NEW.tender_result_id AND r.company_id=NEW.company_id
            )
            BEGIN SELECT RAISE(ABORT,'cross-company tender proposal'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_proposal_company_update
            BEFORE UPDATE ON tender_proposals
            WHEN NOT EXISTS (
              SELECT 1 FROM tender_results r
              WHERE r.id=NEW.tender_result_id AND r.company_id=NEW.company_id
            )
            BEGIN SELECT RAISE(ABORT,'cross-company tender proposal'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_proposal_version_company_insert
            BEFORE INSERT ON tender_proposal_versions
            WHEN NOT EXISTS (
              SELECT 1 FROM tender_proposals p
              WHERE p.id=NEW.proposal_id AND p.company_id=NEW.company_id
            )
            BEGIN SELECT RAISE(ABORT,'cross-company tender proposal version'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_proposal_version_immutable_update
            BEFORE UPDATE ON tender_proposal_versions
            BEGIN SELECT RAISE(ABORT,'tender proposal versions are immutable'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_proposal_item_company_insert
            BEFORE INSERT ON tender_proposal_version_items
            WHEN NOT EXISTS (
              SELECT 1 FROM tender_proposal_versions v
              WHERE v.id=NEW.version_id AND v.company_id=NEW.company_id
            ) OR (NEW.catalog_record_id IS NOT NULL AND NOT EXISTS (
              SELECT 1 FROM records r WHERE r.id=NEW.catalog_record_id
                AND r.company_id=NEW.company_id AND r.deleted_at IS NULL
                AND r.module IN ('produtos','catalogo_servicos')
            ))
            BEGIN SELECT RAISE(ABORT,'cross-company tender proposal item'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_proposal_item_immutable_update
            BEFORE UPDATE ON tender_proposal_version_items
            BEGIN SELECT RAISE(ABORT,'tender proposal items are immutable'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_proposal_item_feasibility_insert
            BEFORE INSERT ON tender_proposal_version_items
            WHEN NEW.catalog_module NOT IN ('produtos','catalogo_servicos')
              OR NEW.catalog_cost_cents < 0
              OR NEW.cost_source NOT IN (
                'INVENTORY_AVERAGE','CATALOG_REFERENCE','MANUAL_VALIDATED'
              )
              OR NEW.available_quantity_micros < 0
              OR NEW.supply_mode NOT IN (
                'UNDEFINED','STOCK','PURCHASE','MANUFACTURE','MIXED',
                'SERVICE_CAPACITY','EXCEPTION'
              )
              OR (NEW.catalog_record_id IS NOT NULL AND EXISTS (
                SELECT 1 FROM records WHERE id=NEW.catalog_record_id
                  AND company_id=NEW.company_id
              ) AND (
                NEW.catalog_module IS NULL OR NEW.catalog_module != (
                  SELECT module FROM records WHERE id=NEW.catalog_record_id
                    AND company_id=NEW.company_id
                )
              ))
              OR (NEW.catalog_record_id IS NULL AND NEW.catalog_module IS NOT NULL)
            BEGIN SELECT RAISE(ABORT,'invalid tender proposal feasibility'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_proposal_decision_company_insert
            BEFORE INSERT ON tender_proposal_decisions
            WHEN NOT EXISTS (
              SELECT 1 FROM tender_proposals p
              WHERE p.id=NEW.proposal_id AND p.company_id=NEW.company_id
                AND p.current_version=NEW.version
            )
            BEGIN SELECT RAISE(ABORT,'cross-company tender proposal decision'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_proposal_decision_immutable_update
            BEFORE UPDATE ON tender_proposal_decisions
            BEGIN SELECT RAISE(ABORT,'tender proposal decisions are immutable'); END;

            DROP TRIGGER IF EXISTS trg_tender_requirement_company_insert;
            DROP TRIGGER IF EXISTS trg_tender_requirement_company_update;
            CREATE TRIGGER trg_tender_requirement_company_insert
            BEFORE INSERT ON tender_document_requirements
            WHEN NOT EXISTS (
              SELECT 1 FROM tender_results r
              WHERE r.id=NEW.tender_result_id AND r.company_id=NEW.company_id
            ) OR (NEW.selected_document_id IS NOT NULL AND NOT EXISTS (
              SELECT 1 FROM company_tender_documents d
              WHERE d.id=NEW.selected_document_id AND d.company_id=NEW.company_id
                AND d.document_type=COALESCE(NEW.vault_document_type,NEW.document_type)
            ))
            BEGIN SELECT RAISE(ABORT,'cross-company tender requirement'); END;
            CREATE TRIGGER trg_tender_requirement_company_update
            BEFORE UPDATE ON tender_document_requirements
            WHEN NOT EXISTS (
              SELECT 1 FROM tender_results r
              WHERE r.id=NEW.tender_result_id AND r.company_id=NEW.company_id
            ) OR (NEW.selected_document_id IS NOT NULL AND NOT EXISTS (
              SELECT 1 FROM company_tender_documents d
              WHERE d.id=NEW.selected_document_id AND d.company_id=NEW.company_id
                AND d.document_type=COALESCE(NEW.vault_document_type,NEW.document_type)
            ))
            BEGIN SELECT RAISE(ABORT,'cross-company tender requirement'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_requirement_document_insert
            BEFORE INSERT ON tender_requirement_documents
            WHEN NOT EXISTS (
              SELECT 1 FROM tender_document_requirements r
              WHERE r.id=NEW.requirement_id AND r.company_id=NEW.company_id
            ) OR NOT EXISTS (
              SELECT 1 FROM company_tender_documents d
              JOIN tender_document_requirements r ON r.id=NEW.requirement_id
              WHERE d.id=NEW.document_id AND d.company_id=NEW.company_id
                AND d.document_type=COALESCE(r.vault_document_type,r.document_type)
            )
            BEGIN SELECT RAISE(ABORT,'cross-company requirement document'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_requirement_document_update
            BEFORE UPDATE ON tender_requirement_documents
            WHEN NOT EXISTS (
              SELECT 1 FROM tender_document_requirements r
              WHERE r.id=NEW.requirement_id AND r.company_id=NEW.company_id
            ) OR NOT EXISTS (
              SELECT 1 FROM company_tender_documents d
              JOIN tender_document_requirements r ON r.id=NEW.requirement_id
              WHERE d.id=NEW.document_id AND d.company_id=NEW.company_id
                AND d.document_type=COALESCE(r.vault_document_type,r.document_type)
            )
            BEGIN SELECT RAISE(ABORT,'cross-company requirement document'); END;
            """
        )
        db.execute(
            """INSERT OR IGNORE INTO tender_requirement_documents
               (requirement_id,company_id,document_id,sort_order,created_at)
               SELECT id,company_id,selected_document_id,0,created_at
               FROM tender_document_requirements WHERE selected_document_id IS NOT NULL"""
        )
        for row in db.execute(
                "SELECT token_hash FROM sessions WHERE public_id IS NULL OR public_id=''"
        ).fetchall():
            db.execute(
                "UPDATE sessions SET public_id=? WHERE token_hash=?",
                (secrets.token_hex(12), row["token_hash"]),
            )
        db.execute(
            "UPDATE sessions SET last_activity_at=COALESCE(last_activity_at,expires_at-?)",
            (SESSION_SECONDS,),
        )
        db.execute(
            "CREATE UNIQUE INDEX IF NOT EXISTS idx_sessions_public_id ON sessions(public_id)"
        )
        telemetry_cutoff = (
            datetime.now(timezone.utc) - timedelta(days=TELEMETRY_RETENTION_DAYS)
        ).isoformat(timespec="seconds")
        db.execute(
            "DELETE FROM system_events WHERE resolved_at IS NOT NULL AND created_at<?",
            (telemetry_cutoff,),
        )

        # Caixa de entrada compartilhada do WhatsApp. O conteúdo permanece em
        # tabelas próprias: o CRM guarda a oportunidade, enquanto conversa e
        # mensagens preservam atribuição, janela de atendimento e recibos do canal.
        db.executescript(
            """
            CREATE TABLE IF NOT EXISTS whatsapp_conversations(
              id INTEGER PRIMARY KEY AUTOINCREMENT,
              company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
              phone_number_id TEXT NOT NULL,
              contact_wa_id TEXT NOT NULL,
              contact_name TEXT,
              team TEXT NOT NULL DEFAULT 'COMERCIAL'
                CHECK(team IN ('COMERCIAL','FINANCEIRO','GESTAO')),
              assigned_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
              crm_record_id INTEGER REFERENCES records(id) ON DELETE SET NULL,
              status TEXT NOT NULL DEFAULT 'OPEN'
                CHECK(status IN ('OPEN','PENDING','CLOSED')),
              customer_window_expires_at TEXT,
              last_inbound_at TEXT,
              last_message_at TEXT NOT NULL,
              created_at TEXT NOT NULL,
              updated_at TEXT NOT NULL,
              revision INTEGER NOT NULL DEFAULT 1,
              UNIQUE(company_id,phone_number_id,contact_wa_id)
            );
            CREATE INDEX IF NOT EXISTS idx_whatsapp_conversations_queue
              ON whatsapp_conversations(company_id,status,team,assigned_user_id,last_message_at DESC);
            CREATE TABLE IF NOT EXISTS whatsapp_messages(
              id INTEGER PRIMARY KEY AUTOINCREMENT,
              company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
              conversation_id INTEGER NOT NULL REFERENCES whatsapp_conversations(id) ON DELETE CASCADE,
              external_id TEXT,
              client_request_id TEXT,
              direction TEXT NOT NULL CHECK(direction IN ('INBOUND','OUTBOUND')),
              message_type TEXT NOT NULL DEFAULT 'text',
              body TEXT NOT NULL DEFAULT '',
              status TEXT NOT NULL,
              sent_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
              occurred_at TEXT NOT NULL,
              raw_sha256 TEXT,
              created_at TEXT NOT NULL,
              UNIQUE(company_id,external_id),
              UNIQUE(company_id,client_request_id)
            );
            CREATE INDEX IF NOT EXISTS idx_whatsapp_messages_conversation
              ON whatsapp_messages(company_id,conversation_id,occurred_at,id);
            CREATE TABLE IF NOT EXISTS whatsapp_quick_replies(
              id INTEGER PRIMARY KEY AUTOINCREMENT,
              company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
              name TEXT NOT NULL,
              category TEXT NOT NULL DEFAULT 'ATENDIMENTO'
                CHECK(category IN ('ATENDIMENTO','COMERCIAL','FINANCEIRO')),
              body TEXT NOT NULL,
              active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),
              created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
              created_at TEXT NOT NULL,
              updated_at TEXT NOT NULL,
              UNIQUE(company_id,name)
            );
            CREATE TABLE IF NOT EXISTS whatsapp_instances(
              id INTEGER PRIMARY KEY AUTOINCREMENT,
              company_id INTEGER NOT NULL UNIQUE REFERENCES companies(id) ON DELETE CASCADE,
              provider TEXT NOT NULL DEFAULT 'UAZAPI' CHECK(provider='UAZAPI'),
              instance_name TEXT NOT NULL,
              device_name TEXT NOT NULL,
              server_url TEXT NOT NULL,
              instance_token_cipher BLOB NOT NULL,
              instance_token_nonce BLOB NOT NULL,
              webhook_public_id TEXT NOT NULL UNIQUE,
              webhook_url TEXT NOT NULL,
              status TEXT NOT NULL DEFAULT 'created'
                CHECK(status IN ('created','connecting','connected','disconnected','hibernated','error')),
              is_connected INTEGER NOT NULL DEFAULT 0 CHECK(is_connected IN (0,1)),
              display_phone TEXT,
              profile_name TEXT,
              last_connection_at TEXT,
              last_error TEXT,
              created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
              created_at TEXT NOT NULL,
              updated_at TEXT NOT NULL,
              revision INTEGER NOT NULL DEFAULT 1
            );
            CREATE INDEX IF NOT EXISTS idx_whatsapp_instances_webhook
              ON whatsapp_instances(webhook_public_id,company_id);
            CREATE TRIGGER IF NOT EXISTS trg_whatsapp_conversation_company_insert
            BEFORE INSERT ON whatsapp_conversations
            WHEN (NEW.assigned_user_id IS NOT NULL AND NOT EXISTS(
              SELECT 1 FROM company_memberships m
              WHERE m.company_id=NEW.company_id AND m.user_id=NEW.assigned_user_id AND m.active=1
            )) OR (NEW.crm_record_id IS NOT NULL AND NOT EXISTS(
              SELECT 1 FROM records r
              WHERE r.id=NEW.crm_record_id AND r.company_id=NEW.company_id AND r.module='crm'
            ))
            BEGIN SELECT RAISE(ABORT,'WhatsApp fora da empresa ou CRM incompatível'); END;
            CREATE TRIGGER IF NOT EXISTS trg_whatsapp_conversation_company_update
            BEFORE UPDATE ON whatsapp_conversations
            WHEN (NEW.assigned_user_id IS NOT NULL AND NOT EXISTS(
              SELECT 1 FROM company_memberships m
              WHERE m.company_id=NEW.company_id AND m.user_id=NEW.assigned_user_id AND m.active=1
            )) OR (NEW.crm_record_id IS NOT NULL AND NOT EXISTS(
              SELECT 1 FROM records r
              WHERE r.id=NEW.crm_record_id AND r.company_id=NEW.company_id AND r.module='crm'
            ))
            BEGIN SELECT RAISE(ABORT,'WhatsApp fora da empresa ou CRM incompatível'); END;
            CREATE TRIGGER IF NOT EXISTS trg_whatsapp_message_company_insert
            BEFORE INSERT ON whatsapp_messages
            WHEN NOT EXISTS(
              SELECT 1 FROM whatsapp_conversations c
              WHERE c.id=NEW.conversation_id AND c.company_id=NEW.company_id
            )
            BEGIN SELECT RAISE(ABORT,'Mensagem WhatsApp fora da empresa'); END;
            CREATE TABLE IF NOT EXISTS customer_followups(
              id INTEGER PRIMARY KEY AUTOINCREMENT,
              company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
              customer_record_id INTEGER NOT NULL REFERENCES records(id) ON DELETE CASCADE,
              purchase_anchor_at TEXT NOT NULL,
              last_sale_record_id INTEGER REFERENCES records(id) ON DELETE SET NULL,
              stage_days INTEGER NOT NULL CHECK(stage_days IN (30,60,90)),
              due_at TEXT NOT NULL,
              status TEXT NOT NULL DEFAULT 'PENDING'
                CHECK(status IN ('PENDING','CONTACTED','DISMISSED','ESCALATED','OBSOLETE')),
              assigned_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
              notification_id INTEGER REFERENCES notifications(id) ON DELETE SET NULL,
              contact_channel TEXT,
              outcome TEXT,
              notes TEXT,
              contacted_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
              contacted_at TEXT,
              created_at TEXT NOT NULL,
              updated_at TEXT NOT NULL,
              UNIQUE(company_id,customer_record_id,purchase_anchor_at,stage_days)
            );
            CREATE INDEX IF NOT EXISTS idx_customer_followups_queue
              ON customer_followups(company_id,status,stage_days,due_at);
            CREATE INDEX IF NOT EXISTS idx_customer_followups_customer
              ON customer_followups(company_id,customer_record_id,purchase_anchor_at);
            CREATE TRIGGER IF NOT EXISTS trg_customer_followup_scope_insert
            BEFORE INSERT ON customer_followups
            WHEN NOT EXISTS(
              SELECT 1 FROM records r WHERE r.id=NEW.customer_record_id
                AND r.company_id=NEW.company_id AND r.module IN ('clientes','fornecedores')
            ) OR (NEW.last_sale_record_id IS NOT NULL AND NOT EXISTS(
              SELECT 1 FROM records r WHERE r.id=NEW.last_sale_record_id
                AND r.company_id=NEW.company_id AND r.module='vendas'
            )) OR (NEW.assigned_user_id IS NOT NULL AND NOT EXISTS(
              SELECT 1 FROM company_memberships m WHERE m.company_id=NEW.company_id
                AND m.user_id=NEW.assigned_user_id AND m.active=1
            ))
            BEGIN SELECT RAISE(ABORT,'Follow-up fora da empresa ou com vínculo incompatível'); END;
            """
        )
        seed_time = utc_now()
        for name, category, body in (
            ("Saudação inicial", "COMERCIAL",
             "Olá, {{nome}}! Sou {{vendedor}} da SECCOL. Recebemos seu contato e gostaria de entender melhor como podemos ajudar."),
            ("Acompanhamento de proposta", "COMERCIAL",
             "Olá, {{nome}}! Passando para acompanhar a proposta {{referencia}}. Posso esclarecer algum ponto?"),
            ("Encaminhamento ao financeiro", "FINANCEIRO",
             "Olá, {{nome}}! Encaminhei sua solicitação ao nosso financeiro. A equipe responsável dará continuidade por este canal."),
        ):
            db.execute(
                """INSERT OR IGNORE INTO whatsapp_quick_replies
                   (company_id,name,category,body,active,created_by,created_at,updated_at)
                   SELECT id,?,?,?,1,NULL,?,? FROM companies""",
                (name, category, body, seed_time, seed_time),
            )

        # Índices alinhados às consultas reais: todos os registros são sempre
        # filtrados pela empresa ativa e, em seguida, por módulo/situação/prazo.
        # Os índices antigos por coluna isolada permanecem por compatibilidade.
        db.executescript(
            """
            CREATE INDEX IF NOT EXISTS idx_records_company_module_active_updated
              ON records(company_id,module,deleted_at,updated_at DESC);
            CREATE INDEX IF NOT EXISTS idx_records_company_status_active_due
              ON records(company_id,status,deleted_at,due_date);
            CREATE INDEX IF NOT EXISTS idx_records_company_subject_active
              ON records(company_id,subject_id,deleted_at);
            CREATE UNIQUE INDEX IF NOT EXISTS idx_records_company_party_document_active
              ON records(
                company_id,
                replace(replace(replace(replace(
                  CAST(json_extract(payload,'$.documento') AS TEXT),
                  '.',''),'-',''),'/',''),' ','')
              )
              WHERE deleted_at IS NULL
                AND module IN ('clientes','fornecedores')
                AND length(replace(replace(replace(replace(
                  CAST(json_extract(payload,'$.documento') AS TEXT),
                  '.',''),'-',''),'/',''),' ','')) IN (11,14);
            CREATE INDEX IF NOT EXISTS idx_subjects_company_status_name
              ON subjects(company_id,status,normalized_name);
            CREATE INDEX IF NOT EXISTS idx_record_subjects_record
              ON record_subjects(record_id,subject_id);

            -- A aplicação já valida esse vínculo; as travas no banco impedem
            -- que importadores ou evoluções futuras criem relação entre empresas.
            CREATE TRIGGER IF NOT EXISTS trg_relationship_same_company_insert
            BEFORE INSERT ON record_relationships
            FOR EACH ROW
            WHEN COALESCE((SELECT company_id FROM records WHERE id=NEW.from_record_id), -1)
                 != COALESCE((SELECT company_id FROM records WHERE id=NEW.to_record_id), -1)
            BEGIN
              SELECT RAISE(ABORT, 'Relacionamentos devem permanecer na mesma empresa');
            END;

            CREATE TRIGGER IF NOT EXISTS trg_record_subject_same_company_insert
            BEFORE INSERT ON record_subjects
            FOR EACH ROW
            WHEN COALESCE((SELECT company_id FROM records WHERE id=NEW.record_id), -1)
                 != COALESCE((SELECT company_id FROM subjects WHERE id=NEW.subject_id), -1)
            BEGIN
              SELECT RAISE(ABORT, 'Assunto deve pertencer à mesma empresa do registro');
            END;
            """
        )

        db.executescript(
            """
            CREATE TABLE IF NOT EXISTS financial_categories (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                name TEXT NOT NULL,
                normalized_name TEXT NOT NULL,
                kind TEXT NOT NULL CHECK(kind IN ('EXPENSE','INCOME','BOTH')),
                active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),
                created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                updated_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                UNIQUE(company_id,normalized_name)
            );
            CREATE INDEX IF NOT EXISTS idx_financial_categories_company_active_kind
              ON financial_categories(company_id,active,kind,name);

            CREATE TABLE IF NOT EXISTS accounting_chart_accounts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                code TEXT NOT NULL,
                name TEXT NOT NULL,
                nature TEXT NOT NULL CHECK(nature IN ('ASSET','LIABILITY','EQUITY','REVENUE','EXPENSE')),
                account_kind TEXT NOT NULL CHECK(account_kind IN ('GROUP','ANALYTICAL')),
                parent_id INTEGER REFERENCES accounting_chart_accounts(id) ON DELETE RESTRICT,
                reference_code TEXT,
                active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),
                created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                updated_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                UNIQUE(company_id,code)
            );
            CREATE INDEX IF NOT EXISTS idx_chart_accounts_company_active_code
              ON accounting_chart_accounts(company_id,active,code);
            CREATE TABLE IF NOT EXISTS cost_centers (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                code TEXT NOT NULL,
                name TEXT NOT NULL,
                active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),
                created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                updated_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                UNIQUE(company_id,code)
            );
            CREATE INDEX IF NOT EXISTS idx_cost_centers_company_active_code
              ON cost_centers(company_id,active,code);
            CREATE TRIGGER IF NOT EXISTS trg_chart_account_parent_scope_insert
            BEFORE INSERT ON accounting_chart_accounts
            WHEN NEW.parent_id IS NOT NULL AND NOT EXISTS(
              SELECT 1 FROM accounting_chart_accounts p WHERE p.id=NEW.parent_id AND p.company_id=NEW.company_id
            )
            BEGIN SELECT RAISE(ABORT,'Conta pai deve pertencer a empresa ativa'); END;
            CREATE TABLE IF NOT EXISTS accounting_journal_entries (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                entry_date TEXT NOT NULL,
                competence_date TEXT NOT NULL,
                memo TEXT NOT NULL,
                source_type TEXT NOT NULL DEFAULT 'MANUAL',
                source_id TEXT,
                reversal_of_id INTEGER REFERENCES accounting_journal_entries(id) ON DELETE RESTRICT,
                created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                created_at TEXT NOT NULL,
                UNIQUE(company_id,reversal_of_id)
            );
            CREATE INDEX IF NOT EXISTS idx_accounting_entries_company_competence
              ON accounting_journal_entries(company_id,competence_date,id);
            CREATE UNIQUE INDEX IF NOT EXISTS idx_accounting_opening_balance_once
              ON accounting_journal_entries(company_id,source_type,source_id)
              WHERE source_type='OPENING_BALANCE';
            CREATE TABLE IF NOT EXISTS accounting_period_closures (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                period TEXT NOT NULL CHECK(period GLOB '20[0-9][0-9]-[0-1][0-9]'),
                status TEXT NOT NULL CHECK(status IN ('CLOSED','REOPENED')),
                close_reason TEXT NOT NULL,
                closed_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                closed_at TEXT NOT NULL,
                reopened_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                reopened_at TEXT,
                reopen_reason TEXT,
                updated_at TEXT NOT NULL,
                UNIQUE(company_id,period)
            );
            CREATE INDEX IF NOT EXISTS idx_accounting_period_closures_company_status
              ON accounting_period_closures(company_id,status,period);
            CREATE TRIGGER IF NOT EXISTS trg_accounting_entry_closed_period
            BEFORE INSERT ON accounting_journal_entries
            WHEN EXISTS(
              SELECT 1 FROM accounting_period_closures p
               WHERE p.company_id=NEW.company_id AND p.period=substr(NEW.competence_date,1,7)
                 AND p.status='CLOSED'
            )
            BEGIN SELECT RAISE(ABORT,'Periodo contabil encerrado'); END;
            CREATE TABLE IF NOT EXISTS accounting_journal_lines (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                entry_id INTEGER NOT NULL REFERENCES accounting_journal_entries(id) ON DELETE RESTRICT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                account_id INTEGER NOT NULL REFERENCES accounting_chart_accounts(id) ON DELETE RESTRICT,
                cost_center_id INTEGER REFERENCES cost_centers(id) ON DELETE RESTRICT,
                debit_cents INTEGER NOT NULL DEFAULT 0 CHECK(debit_cents >= 0),
                credit_cents INTEGER NOT NULL DEFAULT 0 CHECK(credit_cents >= 0),
                memo TEXT,
                CHECK((debit_cents > 0 AND credit_cents = 0) OR (credit_cents > 0 AND debit_cents = 0))
            );
            CREATE INDEX IF NOT EXISTS idx_accounting_lines_company_account
              ON accounting_journal_lines(company_id,account_id,entry_id);
            CREATE TRIGGER IF NOT EXISTS trg_accounting_line_scope_insert
            BEFORE INSERT ON accounting_journal_lines
            WHEN NOT EXISTS(SELECT 1 FROM accounting_chart_accounts a WHERE a.id=NEW.account_id AND a.company_id=NEW.company_id)
              OR (NEW.cost_center_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM cost_centers c WHERE c.id=NEW.cost_center_id AND c.company_id=NEW.company_id))
            BEGIN SELECT RAISE(ABORT,'Linha contabil fora da empresa'); END;
            CREATE TABLE IF NOT EXISTS accounting_financial_mappings (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                financial_module TEXT NOT NULL CHECK(financial_module IN ('contas_pagar','contas_receber')),
                financial_category_id INTEGER NOT NULL REFERENCES financial_categories(id) ON DELETE RESTRICT,
                debit_account_id INTEGER NOT NULL REFERENCES accounting_chart_accounts(id) ON DELETE RESTRICT,
                credit_account_id INTEGER NOT NULL REFERENCES accounting_chart_accounts(id) ON DELETE RESTRICT,
                cost_center_id INTEGER REFERENCES cost_centers(id) ON DELETE RESTRICT,
                active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),
                created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                updated_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                UNIQUE(company_id,financial_module,financial_category_id)
            );
            CREATE INDEX IF NOT EXISTS idx_accounting_financial_mappings_lookup
              ON accounting_financial_mappings(company_id,financial_module,financial_category_id,active);
            CREATE TRIGGER IF NOT EXISTS trg_accounting_mapping_scope_insert
            BEFORE INSERT ON accounting_financial_mappings
            WHEN NOT EXISTS(SELECT 1 FROM financial_categories c WHERE c.id=NEW.financial_category_id AND c.company_id=NEW.company_id)
              OR NOT EXISTS(SELECT 1 FROM accounting_chart_accounts a WHERE a.id=NEW.debit_account_id AND a.company_id=NEW.company_id)
              OR NOT EXISTS(SELECT 1 FROM accounting_chart_accounts a WHERE a.id=NEW.credit_account_id AND a.company_id=NEW.company_id)
              OR (NEW.cost_center_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM cost_centers c WHERE c.id=NEW.cost_center_id AND c.company_id=NEW.company_id))
            BEGIN SELECT RAISE(ABORT,'Mapeamento contabil fora da empresa'); END;
            CREATE TABLE IF NOT EXISTS accounting_financial_mapping_allocations (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                mapping_id INTEGER NOT NULL REFERENCES accounting_financial_mappings(id) ON DELETE CASCADE,
                cost_center_id INTEGER NOT NULL REFERENCES cost_centers(id) ON DELETE RESTRICT,
                allocation_side TEXT NOT NULL CHECK(allocation_side IN ('DEBIT','CREDIT')),
                basis_points INTEGER NOT NULL CHECK(basis_points BETWEEN 1 AND 10000),
                created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                created_at TEXT NOT NULL,
                UNIQUE(mapping_id,cost_center_id)
            );
            CREATE INDEX IF NOT EXISTS idx_accounting_mapping_allocations_lookup
              ON accounting_financial_mapping_allocations(company_id,mapping_id,id);
            CREATE TRIGGER IF NOT EXISTS trg_accounting_mapping_allocation_scope_insert
            BEFORE INSERT ON accounting_financial_mapping_allocations
            WHEN NOT EXISTS(SELECT 1 FROM accounting_financial_mappings m WHERE m.id=NEW.mapping_id AND m.company_id=NEW.company_id)
              OR NOT EXISTS(SELECT 1 FROM cost_centers c WHERE c.id=NEW.cost_center_id AND c.company_id=NEW.company_id)
            BEGIN SELECT RAISE(ABORT,'Rateio contabil fora da empresa'); END;
            CREATE TRIGGER IF NOT EXISTS trg_accounting_mapping_allocation_scope_update
            BEFORE UPDATE OF company_id,mapping_id,cost_center_id ON accounting_financial_mapping_allocations
            WHEN NOT EXISTS(SELECT 1 FROM accounting_financial_mappings m WHERE m.id=NEW.mapping_id AND m.company_id=NEW.company_id)
              OR NOT EXISTS(SELECT 1 FROM cost_centers c WHERE c.id=NEW.cost_center_id AND c.company_id=NEW.company_id)
            BEGIN SELECT RAISE(ABORT,'Rateio contabil fora da empresa'); END;
            CREATE TABLE IF NOT EXISTS accounting_financial_adjustment_rules (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                mapping_id INTEGER NOT NULL REFERENCES accounting_financial_mappings(id) ON DELETE CASCADE,
                adjustment_type TEXT NOT NULL CHECK(adjustment_type IN ('DISCOUNT','INTEREST','FEE')),
                account_id INTEGER NOT NULL REFERENCES accounting_chart_accounts(id) ON DELETE RESTRICT,
                cost_center_id INTEGER REFERENCES cost_centers(id) ON DELETE RESTRICT,
                created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                updated_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                UNIQUE(mapping_id,adjustment_type)
            );
            CREATE INDEX IF NOT EXISTS idx_accounting_adjustment_rules_lookup
              ON accounting_financial_adjustment_rules(company_id,mapping_id,adjustment_type);
            CREATE TRIGGER IF NOT EXISTS trg_accounting_adjustment_rule_scope_insert
            BEFORE INSERT ON accounting_financial_adjustment_rules
            WHEN NOT EXISTS(SELECT 1 FROM accounting_financial_mappings m WHERE m.id=NEW.mapping_id AND m.company_id=NEW.company_id)
              OR NOT EXISTS(SELECT 1 FROM accounting_chart_accounts a WHERE a.id=NEW.account_id AND a.company_id=NEW.company_id)
              OR (NEW.cost_center_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM cost_centers c WHERE c.id=NEW.cost_center_id AND c.company_id=NEW.company_id))
            BEGIN SELECT RAISE(ABORT,'Regra contabil de ajuste fora da empresa'); END;
            CREATE TRIGGER IF NOT EXISTS trg_accounting_adjustment_rule_scope_update
            BEFORE UPDATE OF company_id,mapping_id,account_id,cost_center_id ON accounting_financial_adjustment_rules
            WHEN NOT EXISTS(SELECT 1 FROM accounting_financial_mappings m WHERE m.id=NEW.mapping_id AND m.company_id=NEW.company_id)
              OR NOT EXISTS(SELECT 1 FROM accounting_chart_accounts a WHERE a.id=NEW.account_id AND a.company_id=NEW.company_id)
              OR (NEW.cost_center_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM cost_centers c WHERE c.id=NEW.cost_center_id AND c.company_id=NEW.company_id))
            BEGIN SELECT RAISE(ABORT,'Regra contabil de ajuste fora da empresa'); END;
            """
        )

        # Governanca operacional da participacao em licitacoes. O perfil usa
        # revisao otimista; comprovantes de protocolo sao append-only e ficam
        # fisicamente isolados pela empresa, inclusive em acessos fora da API.
        db.executescript(
            """
            CREATE TABLE IF NOT EXISTS tender_control_profiles (
                tender_result_id INTEGER PRIMARY KEY
                  REFERENCES tender_results(id) ON DELETE CASCADE,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                decision TEXT NOT NULL DEFAULT 'PENDING'
                  CHECK(decision IN ('PENDING','GO','NO_GO')),
                decision_reason TEXT,
                responsible_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
                decided_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                decided_at TEXT,
                revision INTEGER NOT NULL DEFAULT 1 CHECK(revision > 0),
                created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL
            );
            CREATE INDEX IF NOT EXISTS idx_tender_control_profiles_company_decision
              ON tender_control_profiles(company_id,decision,updated_at DESC);
            CREATE TABLE IF NOT EXISTS tender_control_versions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                tender_result_id INTEGER NOT NULL REFERENCES tender_results(id) ON DELETE RESTRICT,
                revision INTEGER NOT NULL CHECK(revision > 0),
                snapshot_json TEXT NOT NULL,
                created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                created_at TEXT NOT NULL,
                UNIQUE(company_id,tender_result_id,revision)
            );
            CREATE INDEX IF NOT EXISTS idx_tender_control_versions_history
              ON tender_control_versions(company_id,tender_result_id,revision DESC);
            CREATE TABLE IF NOT EXISTS tender_milestones (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                tender_result_id INTEGER NOT NULL REFERENCES tender_results(id) ON DELETE CASCADE,
                milestone_type TEXT NOT NULL CHECK(milestone_type IN (
                  'PROPOSAL','CLARIFICATION','SITE_VISIT','SESSION','APPEAL',
                  'QUALIFICATION','CONTRACT','DELIVERY','OTHER'
                )),
                title TEXT NOT NULL,
                due_at TEXT NOT NULL,
                status TEXT NOT NULL DEFAULT 'PENDING'
                  CHECK(status IN ('PENDING','COMPLETED','CANCELLED')),
                source_reference TEXT,
                notes TEXT,
                responsible_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
                completed_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                completed_at TEXT,
                sort_order INTEGER NOT NULL DEFAULT 0 CHECK(sort_order >= 0),
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL
            );
            CREATE INDEX IF NOT EXISTS idx_tender_milestones_due
              ON tender_milestones(company_id,tender_result_id,status,due_at);
            CREATE TABLE IF NOT EXISTS tender_risks (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                tender_result_id INTEGER NOT NULL REFERENCES tender_results(id) ON DELETE CASCADE,
                category TEXT NOT NULL CHECK(category IN (
                  'DOCUMENTAL','TECHNICAL','COMMERCIAL','CAPACITY','FINANCIAL',
                  'PORTAL','CONTRACTUAL','OTHER'
                )),
                title TEXT NOT NULL,
                probability INTEGER NOT NULL CHECK(probability BETWEEN 1 AND 5),
                impact INTEGER NOT NULL CHECK(impact BETWEEN 1 AND 5),
                mitigation TEXT,
                status TEXT NOT NULL DEFAULT 'OPEN'
                  CHECK(status IN ('OPEN','MITIGATED','ACCEPTED')),
                owner_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
                sort_order INTEGER NOT NULL DEFAULT 0 CHECK(sort_order >= 0),
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL
            );
            CREATE INDEX IF NOT EXISTS idx_tender_risks_open
              ON tender_risks(company_id,tender_result_id,status,impact DESC,probability DESC);
            CREATE TABLE IF NOT EXISTS tender_protocol_evidence (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                tender_result_id INTEGER NOT NULL REFERENCES tender_results(id) ON DELETE RESTRICT,
                event_type TEXT NOT NULL CHECK(event_type IN (
                  'PROPOSAL','CLARIFICATION','APPEAL','QUALIFICATION','CONTRACT','BID','OTHER'
                )),
                portal TEXT,
                protocol TEXT,
                occurred_at TEXT NOT NULL,
                filename TEXT NOT NULL,
                mime_type TEXT NOT NULL,
                content BLOB NOT NULL,
                size INTEGER NOT NULL CHECK(size > 0),
                sha256 TEXT NOT NULL,
                notes TEXT,
                created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                created_at TEXT NOT NULL,
                UNIQUE(company_id,tender_result_id,sha256)
            );
            CREATE INDEX IF NOT EXISTS idx_tender_protocol_evidence_history
              ON tender_protocol_evidence(company_id,tender_result_id,occurred_at DESC,id DESC);

            CREATE TRIGGER IF NOT EXISTS trg_tender_control_profile_scope_insert
            BEFORE INSERT ON tender_control_profiles
            WHEN NOT EXISTS(
              SELECT 1 FROM tender_results t
              WHERE t.id=NEW.tender_result_id AND t.company_id=NEW.company_id
            ) OR (NEW.responsible_user_id IS NOT NULL AND NOT EXISTS(
              SELECT 1 FROM company_memberships m WHERE m.company_id=NEW.company_id
                AND m.user_id=NEW.responsible_user_id AND m.active=1
            )) OR (NEW.decided_by IS NOT NULL AND NOT EXISTS(
              SELECT 1 FROM company_memberships m WHERE m.company_id=NEW.company_id
                AND m.user_id=NEW.decided_by AND m.active=1
            )) OR (NEW.created_by IS NOT NULL AND NOT EXISTS(
              SELECT 1 FROM company_memberships m WHERE m.company_id=NEW.company_id
                AND m.user_id=NEW.created_by AND m.active=1
            ))
            BEGIN SELECT RAISE(ABORT,'controle de licitacao fora da empresa'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_control_profile_scope_update
            BEFORE UPDATE ON tender_control_profiles
            WHEN NEW.company_id!=OLD.company_id OR NEW.tender_result_id!=OLD.tender_result_id OR
              NOT EXISTS(
              SELECT 1 FROM tender_results t
              WHERE t.id=NEW.tender_result_id AND t.company_id=NEW.company_id
            ) OR (NEW.responsible_user_id IS NOT NULL AND NOT EXISTS(
              SELECT 1 FROM company_memberships m WHERE m.company_id=NEW.company_id
                AND m.user_id=NEW.responsible_user_id AND m.active=1
            )) OR (NEW.decided_by IS NOT NULL AND NOT EXISTS(
              SELECT 1 FROM company_memberships m WHERE m.company_id=NEW.company_id
                AND m.user_id=NEW.decided_by AND m.active=1
            ))
            BEGIN SELECT RAISE(ABORT,'controle de licitacao fora da empresa'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_control_version_scope_insert
            BEFORE INSERT ON tender_control_versions
            WHEN NOT EXISTS(
              SELECT 1 FROM tender_results t
              WHERE t.id=NEW.tender_result_id AND t.company_id=NEW.company_id
            ) OR (NEW.created_by IS NOT NULL AND NOT EXISTS(
              SELECT 1 FROM company_memberships m WHERE m.company_id=NEW.company_id
                AND m.user_id=NEW.created_by AND m.active=1
            ))
            BEGIN SELECT RAISE(ABORT,'versao do controle fora da empresa'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_control_version_immutable_update
            BEFORE UPDATE ON tender_control_versions
            BEGIN SELECT RAISE(ABORT,'versao do controle e imutavel'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_control_version_immutable_delete
            BEFORE DELETE ON tender_control_versions
            BEGIN SELECT RAISE(ABORT,'versao do controle e imutavel'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_milestone_scope_insert
            BEFORE INSERT ON tender_milestones
            WHEN NOT EXISTS(
              SELECT 1 FROM tender_results t
              WHERE t.id=NEW.tender_result_id AND t.company_id=NEW.company_id
            ) OR (NEW.responsible_user_id IS NOT NULL AND NOT EXISTS(
              SELECT 1 FROM company_memberships m WHERE m.company_id=NEW.company_id
                AND m.user_id=NEW.responsible_user_id AND m.active=1
            )) OR (NEW.completed_by IS NOT NULL AND NOT EXISTS(
              SELECT 1 FROM company_memberships m WHERE m.company_id=NEW.company_id
                AND m.user_id=NEW.completed_by AND m.active=1
            ))
            BEGIN SELECT RAISE(ABORT,'marco de licitacao fora da empresa'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_milestone_scope_update
            BEFORE UPDATE ON tender_milestones
            WHEN NEW.company_id!=OLD.company_id OR NEW.tender_result_id!=OLD.tender_result_id OR
              (NEW.responsible_user_id IS NOT NULL AND NOT EXISTS(
                SELECT 1 FROM company_memberships m WHERE m.company_id=NEW.company_id
                  AND m.user_id=NEW.responsible_user_id AND m.active=1
              )) OR (NEW.completed_by IS NOT NULL AND NOT EXISTS(
                SELECT 1 FROM company_memberships m WHERE m.company_id=NEW.company_id
                  AND m.user_id=NEW.completed_by AND m.active=1
              ))
            BEGIN SELECT RAISE(ABORT,'marco de licitacao fora da empresa'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_risk_scope_insert
            BEFORE INSERT ON tender_risks
            WHEN NOT EXISTS(
              SELECT 1 FROM tender_results t
              WHERE t.id=NEW.tender_result_id AND t.company_id=NEW.company_id
            ) OR (NEW.owner_user_id IS NOT NULL AND NOT EXISTS(
              SELECT 1 FROM company_memberships m WHERE m.company_id=NEW.company_id
                AND m.user_id=NEW.owner_user_id AND m.active=1
            ))
            BEGIN SELECT RAISE(ABORT,'risco de licitacao fora da empresa'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_risk_scope_update
            BEFORE UPDATE ON tender_risks
            WHEN NEW.company_id!=OLD.company_id OR NEW.tender_result_id!=OLD.tender_result_id OR
              (NEW.owner_user_id IS NOT NULL AND NOT EXISTS(
                SELECT 1 FROM company_memberships m WHERE m.company_id=NEW.company_id
                  AND m.user_id=NEW.owner_user_id AND m.active=1
              ))
            BEGIN SELECT RAISE(ABORT,'risco de licitacao fora da empresa'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_evidence_scope_insert
            BEFORE INSERT ON tender_protocol_evidence
            WHEN NOT EXISTS(
              SELECT 1 FROM tender_results t
              WHERE t.id=NEW.tender_result_id AND t.company_id=NEW.company_id
            ) OR (NEW.created_by IS NOT NULL AND NOT EXISTS(
              SELECT 1 FROM company_memberships m WHERE m.company_id=NEW.company_id
                AND m.user_id=NEW.created_by AND m.active=1
            ))
            BEGIN SELECT RAISE(ABORT,'comprovante de licitacao fora da empresa'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_evidence_immutable_update
            BEFORE UPDATE ON tender_protocol_evidence
            BEGIN SELECT RAISE(ABORT,'comprovante de protocolo e imutavel'); END;
            CREATE TRIGGER IF NOT EXISTS trg_tender_evidence_immutable_delete
            BEFORE DELETE ON tender_protocol_evidence
            BEGIN SELECT RAISE(ABORT,'comprovante de protocolo e imutavel'); END;
            """
        )

        now = utc_now()
        default_holding = db.execute("SELECT id FROM holdings ORDER BY id LIMIT 1").fetchone()
        if default_holding:
            default_holding_id = default_holding["id"]
        else:
            default_holding_id = db.execute(
                "INSERT INTO holdings(name,created_at,updated_at) VALUES(?,?,?)",
                ("Holding principal", now, now),
            ).lastrowid
        default_company = db.execute("SELECT id FROM companies ORDER BY id LIMIT 1").fetchone()
        if not default_company:
            legacy = db.execute("SELECT value FROM settings WHERE key='company'").fetchone()
            legacy_company = json.loads(legacy["value"] or "{}") if legacy else {}
            cursor = db.execute(
                """INSERT INTO companies
                   (name,cnpj,phone,address,created_at,updated_at,holding_id)
                   VALUES(?,?,?,?,?,?,?)""",
                (legacy_company.get("name") or "SECCOL", legacy_company.get("cnpj"),
                 legacy_company.get("phone"), legacy_company.get("address"), now, now,
                 default_holding_id),
            )
            default_company_id = cursor.lastrowid
        else:
            default_company_id = default_company["id"]
        db.execute(
            "UPDATE companies SET holding_id=? WHERE holding_id IS NULL",
            (default_holding_id,),
        )
        for company in db.execute("SELECT id,name,cnpj FROM companies").fetchall():
            self.ensure_company_structure(
                company["id"], company["name"], company["cnpj"], now=now,
            )
            self.seed_financial_categories(company["id"], now=now)

        self.migrate_financial_categories()

        for table in ("records", "subjects", "sessions", "audit_log", "tender_searches",
                      "tender_results", "record_versions"):
            db.execute(f"UPDATE {table} SET company_id=? WHERE company_id IS NULL", (default_company_id,))

        # A chave normalizada inclui a empresa para permitir assuntos iguais em empresas distintas.
        subject_rows = db.execute("SELECT id,company_id,normalized_name FROM subjects").fetchall()
        for subject in subject_rows:
            prefix = f'{subject["company_id"]}:'
            if not str(subject["normalized_name"] or "").startswith(prefix):
                db.execute("UPDATE subjects SET normalized_name=? WHERE id=?",
                           (prefix + str(subject["normalized_name"] or ""), subject["id"]))

        users = db.execute("SELECT id,role,created_at,updated_at FROM users").fetchall()
        for user in users:
            db.execute(
                """INSERT OR IGNORE INTO company_memberships
                   (company_id,user_id,role,permissions,active,created_at,updated_at)
                   VALUES(?,?,?,'{}',1,?,?)""",
                (default_company_id, user["id"], user["role"], user["created_at"], user["updated_at"]),
            )
        db.execute("CREATE INDEX IF NOT EXISTS idx_records_company_module ON records(company_id,module)")
        db.execute("CREATE INDEX IF NOT EXISTS idx_subjects_company ON subjects(company_id)")
        db.execute("CREATE INDEX IF NOT EXISTS idx_tender_results_company ON tender_results(company_id,status)")
        db.execute(
            """UPDATE approvals SET requested_by=COALESCE(requested_by,
                   (SELECT created_by FROM records WHERE records.id=approvals.record_id)),
                   request_comment=COALESCE(request_comment,comment),
                   record_revision=COALESCE(record_revision,1)"""
        )
        db.execute(
            """UPDATE notifications SET module=(
                   SELECT r.module FROM records r
                   WHERE r.id=notifications.record_id AND r.company_id=notifications.company_id
                 )
               WHERE module IS NULL AND record_id IS NOT NULL"""
        )
        db.execute(
            """UPDATE notifications SET category=CASE
                 WHEN module='whatsapp' THEN 'whatsapp'
                 WHEN module='crm' THEN 'crm'
                 WHEN module='editais' THEN 'tenders'
                 WHEN record_id IS NOT NULL THEN 'approvals'
                 ELSE 'system' END
               WHERE category IS NULL OR category='' OR category='system'"""
        )
        db.execute(
            """UPDATE approvals SET status='Cancelada por migração'
               WHERE status='Pendente' AND EXISTS (
                 SELECT 1 FROM approvals newer
                 WHERE newer.company_id=approvals.company_id
                   AND newer.record_id=approvals.record_id
                   AND newer.approval_type=approvals.approval_type
                   AND newer.status='Pendente' AND newer.id>approvals.id
               )"""
        )
        db.execute(
            """CREATE UNIQUE INDEX IF NOT EXISTS idx_approvals_one_pending
               ON approvals(company_id,record_id,approval_type) WHERE status='Pendente'"""
        )
        db.execute(
            """UPDATE tender_jobs SET status='failed',finished_at=?,
               error_detail='Execução interrompida por reinicialização do servidor.'
               WHERE status IN ('queued','running')""",
            (utc_now(),),
        )
        db.execute(
            """UPDATE tender_retry_queue SET status='PENDING',retry_job_id=NULL,
               next_attempt_at=?,last_error=COALESCE(last_error,
               'Retentativa retomada após reinicialização.'),updated_at=?
               WHERE status='RUNNING'""",
            (utc_now(), utc_now()),
        )
        db.execute(
            """CREATE UNIQUE INDEX IF NOT EXISTS idx_tender_jobs_one_active
               ON tender_jobs(company_id) WHERE status IN ('queued','running')"""
        )
        self.upgrade_financial_ledger()
        self.initialize_hr_schema()
