    def initialize_hr_schema(self) -> None:
        """Instala o domínio segregado de vínculos, ponto e folha."""
        self.connection().executescript(
            """
            CREATE TABLE IF NOT EXISTS hr_employments (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                employee_record_id INTEGER NOT NULL REFERENCES records(id) ON DELETE RESTRICT,
                branch_id INTEGER NOT NULL REFERENCES branches(id) ON DELETE RESTRICT,
                registration TEXT NOT NULL,
                status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','ON_LEAVE','TERMINATED')),
                admission_date TEXT NOT NULL,
                termination_date TEXT,
                employment_type TEXT NOT NULL DEFAULT 'CLT' CHECK(employment_type IN ('CLT','APPRENTICE','TEMPORARY')),
                esocial_category TEXT NOT NULL DEFAULT '101',
                job_title TEXT NOT NULL,
                department TEXT NOT NULL,
                monthly_salary_cents INTEGER NOT NULL CHECK(monthly_salary_cents > 0),
                monthly_divisor INTEGER NOT NULL DEFAULT 220 CHECK(monthly_divisor BETWEEN 1 AND 400),
                weekly_minutes INTEGER NOT NULL DEFAULT 2640 CHECK(weekly_minutes BETWEEN 1 AND 3600),
                dependents_ir INTEGER NOT NULL DEFAULT 0 CHECK(dependents_ir BETWEEN 0 AND 99),
                overtime_rate_bp INTEGER NOT NULL DEFAULT 5000 CHECK(overtime_rate_bp BETWEEN 0 AND 30000),
                deduct_absence INTEGER NOT NULL DEFAULT 1 CHECK(deduct_absence IN (0,1)),
                schedule_code TEXT NOT NULL DEFAULT 'PADRAO',
                schedule_json TEXT NOT NULL DEFAULT '{}',
                revision INTEGER NOT NULL DEFAULT 1,
                created_by INTEGER REFERENCES users(id),
                updated_by INTEGER REFERENCES users(id),
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                UNIQUE(company_id,employee_record_id),
                UNIQUE(company_id,registration)
            );
            CREATE INDEX IF NOT EXISTS idx_hr_employments_company_status
              ON hr_employments(company_id,status,employee_record_id);
            CREATE TABLE IF NOT EXISTS hr_time_imports (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                branch_id INTEGER NOT NULL REFERENCES branches(id) ON DELETE RESTRICT,
                format TEXT NOT NULL CHECK(format IN ('AFD004','CSV')),
                filename TEXT NOT NULL,
                sha256 TEXT NOT NULL,
                period_start TEXT,
                period_end TEXT,
                rep_type INTEGER CHECK(rep_type IN (1,2,3)),
                rep_identifier TEXT,
                imported_count INTEGER NOT NULL DEFAULT 0,
                duplicate_count INTEGER NOT NULL DEFAULT 0,
                unmatched_count INTEGER NOT NULL DEFAULT 0,
                warnings_json TEXT NOT NULL DEFAULT '[]',
                imported_by INTEGER REFERENCES users(id),
                imported_at TEXT NOT NULL,
                UNIQUE(company_id,sha256)
            );
            CREATE TABLE IF NOT EXISTS hr_time_punches (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                employment_id INTEGER NOT NULL REFERENCES hr_employments(id) ON DELETE RESTRICT,
                import_id INTEGER REFERENCES hr_time_imports(id) ON DELETE RESTRICT,
                occurred_at TEXT NOT NULL,
                recorded_at TEXT,
                source TEXT NOT NULL CHECK(source IN ('AFD_REP_C_A','AFD_REP_P','CLOCK_CSV','MANUAL')),
                external_id TEXT NOT NULL,
                nsr TEXT,
                collector TEXT,
                offline INTEGER NOT NULL DEFAULT 0 CHECK(offline IN (0,1)),
                source_hash TEXT NOT NULL,
                reason TEXT,
                created_by INTEGER REFERENCES users(id),
                created_at TEXT NOT NULL,
                UNIQUE(company_id,source,external_id)
            );
            CREATE INDEX IF NOT EXISTS idx_hr_time_punches_period
              ON hr_time_punches(company_id,employment_id,occurred_at);
            CREATE TABLE IF NOT EXISTS hr_payroll_events (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                employment_id INTEGER NOT NULL REFERENCES hr_employments(id) ON DELETE RESTRICT,
                period TEXT NOT NULL,
                code TEXT NOT NULL,
                description TEXT NOT NULL,
                kind TEXT NOT NULL CHECK(kind IN ('EARNING','DEDUCTION')),
                amount_cents INTEGER NOT NULL CHECK(amount_cents > 0),
                incidence_inss INTEGER NOT NULL DEFAULT 1 CHECK(incidence_inss IN (0,1)),
                incidence_irrf INTEGER NOT NULL DEFAULT 1 CHECK(incidence_irrf IN (0,1)),
                incidence_fgts INTEGER NOT NULL DEFAULT 1 CHECK(incidence_fgts IN (0,1)),
                reason TEXT NOT NULL,
                created_by INTEGER REFERENCES users(id),
                created_at TEXT NOT NULL,
                UNIQUE(company_id,employment_id,period,code)
            );
            CREATE TABLE IF NOT EXISTS hr_payroll_rubrics (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                code TEXT NOT NULL,
                description TEXT NOT NULL,
                kind TEXT NOT NULL CHECK(kind IN ('EARNING','DEDUCTION')),
                effective_from TEXT NOT NULL,
                effective_until TEXT,
                esocial_nature_code TEXT NOT NULL,
                cod_inc_cp TEXT NOT NULL,
                cod_inc_irrf TEXT NOT NULL,
                cod_inc_fgts TEXT NOT NULL,
                inss_effect TEXT NOT NULL CHECK(inss_effect IN ('BASE','NONE')),
                irrf_effect TEXT NOT NULL CHECK(irrf_effect IN ('BASE','DEDUCT','NONE')),
                fgts_effect TEXT NOT NULL CHECK(fgts_effect IN ('BASE','NONE')),
                normative_source_url TEXT NOT NULL,
                review_note TEXT NOT NULL,
                reviewed_by INTEGER NOT NULL REFERENCES users(id),
                reviewed_at TEXT NOT NULL,
                active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),
                created_at TEXT NOT NULL,
                UNIQUE(company_id,code,effective_from)
            );
            CREATE INDEX IF NOT EXISTS idx_hr_rubrics_period
              ON hr_payroll_rubrics(company_id,active,effective_from,effective_until,code);
            CREATE TABLE IF NOT EXISTS hr_compliance_records (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                kind TEXT NOT NULL CHECK(kind IN ('COLLECTIVE_INSTRUMENT','ESOCIAL_REGISTRATION','SST_PROGRAM','OCCUPATIONAL_HEALTH')),
                title TEXT NOT NULL,
                status TEXT NOT NULL CHECK(status IN ('REVIEWED','NOT_APPLICABLE')),
                identifier TEXT,
                effective_from TEXT NOT NULL,
                effective_until TEXT,
                evidence_url TEXT,
                evidence_sha256 TEXT,
                review_note TEXT NOT NULL,
                reviewed_by INTEGER NOT NULL REFERENCES users(id),
                reviewed_at TEXT NOT NULL,
                created_at TEXT NOT NULL
            );
            CREATE INDEX IF NOT EXISTS idx_hr_compliance_period
              ON hr_compliance_records(company_id,kind,effective_from,effective_until,id);
            CREATE TABLE IF NOT EXISTS hr_lifecycle_events (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                employment_id INTEGER NOT NULL REFERENCES hr_employments(id) ON DELETE RESTRICT,
                event_type TEXT NOT NULL CHECK(event_type IN ('ADMISSION','CONTRACT_CHANGE','LEAVE','RETURN','VACATION','TERMINATION','THIRTEENTH','SST_CAT','SST_ASO','SST_EXPOSURE')),
                esocial_event_code TEXT NOT NULL,
                event_date TEXT NOT NULL,
                end_date TEXT,
                legal_deadline TEXT,
                status TEXT NOT NULL DEFAULT 'REVIEWED' CHECK(status IN ('REVIEWED','EXPORTED')),
                detail_json TEXT NOT NULL,
                reason TEXT NOT NULL,
                reviewed_by INTEGER NOT NULL REFERENCES users(id),
                reviewed_at TEXT NOT NULL,
                created_at TEXT NOT NULL
            );
            CREATE INDEX IF NOT EXISTS idx_hr_lifecycle_period
              ON hr_lifecycle_events(company_id,event_date,event_type,employment_id);
            CREATE TABLE IF NOT EXISTS hr_payroll_runs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                period TEXT NOT NULL,
                payroll_type TEXT NOT NULL DEFAULT 'MONTHLY' CHECK(payroll_type IN ('MONTHLY','THIRTEENTH')),
                status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','CLOSED')),
                legal_table_version TEXT NOT NULL,
                parameters_json TEXT NOT NULL,
                gross_cents INTEGER NOT NULL DEFAULT 0,
                deductions_cents INTEGER NOT NULL DEFAULT 0,
                net_cents INTEGER NOT NULL DEFAULT 0,
                employer_fgts_cents INTEGER NOT NULL DEFAULT 0,
                revision INTEGER NOT NULL DEFAULT 1,
                calculated_by INTEGER REFERENCES users(id),
                calculated_at TEXT NOT NULL,
                closed_by INTEGER REFERENCES users(id),
                closed_at TEXT,
                close_reason TEXT,
                UNIQUE(company_id,period,payroll_type)
            );
            CREATE TABLE IF NOT EXISTS hr_payroll_items (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                payroll_run_id INTEGER NOT NULL REFERENCES hr_payroll_runs(id) ON DELETE CASCADE,
                employment_id INTEGER NOT NULL REFERENCES hr_employments(id) ON DELETE RESTRICT,
                employee_snapshot_json TEXT NOT NULL,
                timesheet_snapshot_json TEXT NOT NULL,
                calculation_json TEXT NOT NULL,
                gross_cents INTEGER NOT NULL,
                deductions_cents INTEGER NOT NULL,
                net_cents INTEGER NOT NULL,
                fgts_cents INTEGER NOT NULL,
                UNIQUE(payroll_run_id,employment_id)
            );
            CREATE TRIGGER IF NOT EXISTS trg_hr_employment_scope_insert
            BEFORE INSERT ON hr_employments FOR EACH ROW
            WHEN COALESCE((SELECT company_id FROM records WHERE id=NEW.employee_record_id AND module='colaboradores'),-1) != NEW.company_id
              OR COALESCE((SELECT company_id FROM branches WHERE id=NEW.branch_id),-1) != NEW.company_id
            BEGIN SELECT RAISE(ABORT,'Vínculo de RH fora da empresa'); END;
            CREATE TRIGGER IF NOT EXISTS trg_hr_employment_scope_update
            BEFORE UPDATE OF company_id,employee_record_id,branch_id ON hr_employments FOR EACH ROW
            WHEN COALESCE((SELECT company_id FROM records WHERE id=NEW.employee_record_id AND module='colaboradores'),-1) != NEW.company_id
              OR COALESCE((SELECT company_id FROM branches WHERE id=NEW.branch_id),-1) != NEW.company_id
            BEGIN SELECT RAISE(ABORT,'Vínculo de RH fora da empresa'); END;
            CREATE TRIGGER IF NOT EXISTS trg_hr_punch_scope_insert
            BEFORE INSERT ON hr_time_punches FOR EACH ROW
            WHEN COALESCE((SELECT company_id FROM hr_employments WHERE id=NEW.employment_id),-1) != NEW.company_id
            BEGIN SELECT RAISE(ABORT,'Marcação fora da empresa'); END;
            CREATE TRIGGER IF NOT EXISTS trg_hr_punch_immutable_update
            BEFORE UPDATE ON hr_time_punches BEGIN SELECT RAISE(ABORT,'Marcação de ponto é imutável'); END;
            CREATE TRIGGER IF NOT EXISTS trg_hr_punch_immutable_delete
            BEFORE DELETE ON hr_time_punches BEGIN SELECT RAISE(ABORT,'Marcação de ponto é imutável'); END;
            DROP TRIGGER IF EXISTS trg_hr_import_immutable_update;
            CREATE TRIGGER trg_hr_import_immutable_update
            BEFORE UPDATE OF company_id,branch_id,format,filename,sha256,period_start,period_end,
              rep_type,rep_identifier,imported_by,imported_at ON hr_time_imports
            BEGIN SELECT RAISE(ABORT,'Importação de ponto é imutável'); END;
            CREATE TRIGGER IF NOT EXISTS trg_hr_import_immutable_delete
            BEFORE DELETE ON hr_time_imports BEGIN SELECT RAISE(ABORT,'Importação de ponto é imutável'); END;
            CREATE TRIGGER IF NOT EXISTS trg_hr_payroll_item_scope_insert
            BEFORE INSERT ON hr_payroll_items FOR EACH ROW
            WHEN COALESCE((SELECT company_id FROM hr_payroll_runs WHERE id=NEW.payroll_run_id),-1) != NEW.company_id
              OR COALESCE((SELECT company_id FROM hr_employments WHERE id=NEW.employment_id),-1) != NEW.company_id
            BEGIN SELECT RAISE(ABORT,'Item de folha fora da empresa'); END;
            CREATE TRIGGER IF NOT EXISTS trg_hr_rubric_immutable_update
            BEFORE UPDATE ON hr_payroll_rubrics BEGIN SELECT RAISE(ABORT,'Rubrica revisada é imutável; crie nova vigência'); END;
            CREATE TRIGGER IF NOT EXISTS trg_hr_rubric_immutable_delete
            BEFORE DELETE ON hr_payroll_rubrics BEGIN SELECT RAISE(ABORT,'Rubrica revisada é imutável'); END;
            CREATE TRIGGER IF NOT EXISTS trg_hr_compliance_immutable_update
            BEFORE UPDATE ON hr_compliance_records BEGIN SELECT RAISE(ABORT,'Evidência de conformidade é imutável'); END;
            CREATE TRIGGER IF NOT EXISTS trg_hr_compliance_immutable_delete
            BEFORE DELETE ON hr_compliance_records BEGIN SELECT RAISE(ABORT,'Evidência de conformidade é imutável'); END;
            CREATE TRIGGER IF NOT EXISTS trg_hr_lifecycle_scope_insert
            BEFORE INSERT ON hr_lifecycle_events FOR EACH ROW
            WHEN COALESCE((SELECT company_id FROM hr_employments WHERE id=NEW.employment_id),-1) != NEW.company_id
            BEGIN SELECT RAISE(ABORT,'Evento trabalhista fora da empresa'); END;
            CREATE TRIGGER IF NOT EXISTS trg_hr_lifecycle_immutable_update
            BEFORE UPDATE ON hr_lifecycle_events BEGIN SELECT RAISE(ABORT,'Evento trabalhista revisado é imutável'); END;
            CREATE TRIGGER IF NOT EXISTS trg_hr_lifecycle_immutable_delete
            BEFORE DELETE ON hr_lifecycle_events BEGIN SELECT RAISE(ABORT,'Evento trabalhista revisado é imutável'); END;
            CREATE TRIGGER IF NOT EXISTS trg_hr_closed_run_immutable
            BEFORE UPDATE ON hr_payroll_runs FOR EACH ROW WHEN OLD.status='CLOSED'
            BEGIN SELECT RAISE(ABORT,'Folha fechada é imutável'); END;
            CREATE TRIGGER IF NOT EXISTS trg_hr_closed_item_update
            BEFORE UPDATE ON hr_payroll_items FOR EACH ROW
            WHEN COALESCE((SELECT status FROM hr_payroll_runs WHERE id=OLD.payroll_run_id),'CLOSED')='CLOSED'
            BEGIN SELECT RAISE(ABORT,'Item de folha fechada é imutável'); END;
            CREATE TRIGGER IF NOT EXISTS trg_hr_closed_item_delete
            BEFORE DELETE ON hr_payroll_items FOR EACH ROW
            WHEN COALESCE((SELECT status FROM hr_payroll_runs WHERE id=OLD.payroll_run_id),'CLOSED')='CLOSED'
            BEGIN SELECT RAISE(ABORT,'Item de folha fechada é imutável'); END;
            """
        )
        db = self.connection()
        import_columns = {row["name"] for row in db.execute("PRAGMA table_info(hr_time_imports)")}
        if "rep_type" not in import_columns:
            db.execute("ALTER TABLE hr_time_imports ADD COLUMN rep_type INTEGER")
        if "rep_identifier" not in import_columns:
            db.execute("ALTER TABLE hr_time_imports ADD COLUMN rep_identifier TEXT")
        event_columns = {row["name"] for row in db.execute("PRAGMA table_info(hr_payroll_events)")}
        if "incidence_irrf" not in event_columns:
            db.execute("ALTER TABLE hr_payroll_events ADD COLUMN incidence_irrf INTEGER NOT NULL DEFAULT 1")
        if "rubric_id" not in event_columns:
            db.execute("ALTER TABLE hr_payroll_events ADD COLUMN rubric_id INTEGER REFERENCES hr_payroll_rubrics(id)")
        if "rubric_snapshot_json" not in event_columns:
            db.execute("ALTER TABLE hr_payroll_events ADD COLUMN rubric_snapshot_json TEXT")

    def initialize_reporting_schema(self) -> None:
        """Instala modelos de relatório sem permitir consultas arbitrárias."""
        self.connection().executescript(
            """
            CREATE TABLE IF NOT EXISTS report_templates (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                owner_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
                name TEXT NOT NULL,
                dataset TEXT NOT NULL,
                definition_json TEXT NOT NULL,
                shared INTEGER NOT NULL DEFAULT 0 CHECK(shared IN (0,1)),
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                UNIQUE(company_id,owner_id,name)
            );
            CREATE INDEX IF NOT EXISTS idx_report_templates_company
              ON report_templates(company_id,shared,owner_id,name);
            CREATE INDEX IF NOT EXISTS idx_reporting_records_grouped
              ON records(company_id,module,status,created_at,amount);
            CREATE TRIGGER IF NOT EXISTS trg_report_template_owner_scope_insert
            BEFORE INSERT ON report_templates FOR EACH ROW
            WHEN COALESCE((SELECT company_id FROM company_memberships
                            WHERE company_id=NEW.company_id AND user_id=NEW.owner_id AND active=1),-1)
                 != NEW.company_id
            BEGIN SELECT RAISE(ABORT,'Modelo de relatório fora da empresa'); END;
            """
        )

    def upgrade_financial_ledger(self) -> None:
        """Evolui baixas integrais legadas para um ledger financeiro multi-evento."""
        db = self.connection()
        columns = {
            row["name"] for row in db.execute(
                "PRAGMA table_info(financial_settlements)"
            ).fetchall()
        }
        if columns and "entry_type" not in columns:
            db.executescript(
                """
                DROP TRIGGER IF EXISTS trg_financial_settlement_scope_insert;
                DROP TRIGGER IF EXISTS trg_financial_settlement_immutable_update;
                DROP TRIGGER IF EXISTS trg_financial_settlement_immutable_delete;
                DROP INDEX IF EXISTS idx_financial_settlements_company;
                ALTER TABLE financial_settlements RENAME TO financial_settlements_legacy_237;
                """
            )
        db.executescript(
            """
            CREATE TABLE IF NOT EXISTS bank_statement_entries (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                external_id TEXT NOT NULL,
                booking_date TEXT NOT NULL,
                direction TEXT NOT NULL CHECK(direction IN ('IN','OUT')),
                amount_cents INTEGER NOT NULL CHECK(amount_cents > 0),
                memo TEXT NOT NULL DEFAULT '',
                source_filename TEXT NOT NULL,
                matched_cash_record_id INTEGER UNIQUE REFERENCES records(id) ON DELETE RESTRICT,
                matched_by INTEGER REFERENCES users(id),
                matched_at TEXT,
                imported_by INTEGER REFERENCES users(id),
                imported_at TEXT NOT NULL,
                UNIQUE(company_id,external_id)
            );
            CREATE INDEX IF NOT EXISTS idx_bank_statement_company_date
              ON bank_statement_entries(company_id,booking_date,id);
            CREATE TABLE IF NOT EXISTS bank_accounts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                name TEXT NOT NULL,
                bank_code TEXT NOT NULL,
                bank_name TEXT,
                branch_code TEXT NOT NULL,
                account_last4 TEXT NOT NULL,
                account_type TEXT NOT NULL CHECK(account_type IN ('CHECKING','SAVINGS','PAYMENT')),
                account_fingerprint TEXT NOT NULL,
                active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),
                created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                updated_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                UNIQUE(company_id,account_fingerprint)
            );
            CREATE INDEX IF NOT EXISTS idx_bank_accounts_company_active
              ON bank_accounts(company_id,active,name,id);
            CREATE TRIGGER IF NOT EXISTS trg_bank_statement_scope_insert
            BEFORE INSERT ON bank_statement_entries
            WHEN NEW.matched_cash_record_id IS NOT NULL AND COALESCE((
                SELECT company_id FROM records WHERE id=NEW.matched_cash_record_id
                  AND module='caixa'
            ),-1) != NEW.company_id
            BEGIN SELECT RAISE(ABORT,'Conciliação bancária fora da empresa'); END;
            CREATE TRIGGER IF NOT EXISTS trg_bank_statement_scope_update
            BEFORE UPDATE OF company_id,matched_cash_record_id ON bank_statement_entries
            WHEN NEW.matched_cash_record_id IS NOT NULL AND COALESCE((
                SELECT company_id FROM records WHERE id=NEW.matched_cash_record_id
                  AND module='caixa'
            ),-1) != NEW.company_id
            BEGIN SELECT RAISE(ABORT,'Conciliação bancária fora da empresa'); END;

            CREATE TABLE IF NOT EXISTS financial_settlements (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
                financial_record_id INTEGER NOT NULL REFERENCES records(id) ON DELETE RESTRICT,
                cash_record_id INTEGER NOT NULL UNIQUE REFERENCES records(id) ON DELETE RESTRICT,
                entry_type TEXT NOT NULL DEFAULT 'SETTLEMENT'
                  CHECK(entry_type IN ('SETTLEMENT','REVERSAL')),
                direction TEXT NOT NULL CHECK(direction IN ('IN','OUT')),
                principal_cents INTEGER NOT NULL CHECK(principal_cents > 0),
                discount_cents INTEGER NOT NULL DEFAULT 0 CHECK(discount_cents >= 0),
                interest_cents INTEGER NOT NULL DEFAULT 0 CHECK(interest_cents >= 0),
                fee_cents INTEGER NOT NULL DEFAULT 0 CHECK(fee_cents >= 0),
                cash_amount_cents INTEGER NOT NULL CHECK(cash_amount_cents > 0),
                settled_at TEXT NOT NULL,
                account TEXT NOT NULL,
                payment_method TEXT NOT NULL,
                note TEXT NOT NULL DEFAULT '',
                reverses_settlement_id INTEGER REFERENCES financial_settlements(id) ON DELETE RESTRICT,
                created_by INTEGER REFERENCES users(id),
                created_at TEXT NOT NULL
            );
            CREATE INDEX IF NOT EXISTS idx_financial_settlements_company
              ON financial_settlements(company_id,settled_at,id);
            CREATE INDEX IF NOT EXISTS idx_financial_settlements_title
              ON financial_settlements(company_id,financial_record_id,id);
            CREATE UNIQUE INDEX IF NOT EXISTS idx_financial_settlement_one_reversal
              ON financial_settlements(reverses_settlement_id)
              WHERE reverses_settlement_id IS NOT NULL;
            CREATE TRIGGER IF NOT EXISTS trg_financial_settlement_scope_insert
            BEFORE INSERT ON financial_settlements
            WHEN COALESCE((SELECT company_id FROM records WHERE id=NEW.financial_record_id
                            AND module IN ('contas_pagar','contas_receber')),-1) != NEW.company_id
              OR COALESCE((SELECT company_id FROM records WHERE id=NEW.cash_record_id
                            AND module='caixa'),-1) != NEW.company_id
              OR (NEW.entry_type='SETTLEMENT' AND NEW.direction != CASE (
                    SELECT module FROM records WHERE id=NEW.financial_record_id
                  ) WHEN 'contas_receber' THEN 'IN' ELSE 'OUT' END)
              OR (NEW.entry_type='REVERSAL' AND NEW.direction = CASE (
                    SELECT module FROM records WHERE id=NEW.financial_record_id
                  ) WHEN 'contas_receber' THEN 'IN' ELSE 'OUT' END)
              OR (NEW.entry_type='SETTLEMENT' AND NEW.reverses_settlement_id IS NOT NULL)
              OR (NEW.entry_type='REVERSAL' AND COALESCE((
                    SELECT company_id FROM financial_settlements
                    WHERE id=NEW.reverses_settlement_id AND entry_type='SETTLEMENT'
                      AND financial_record_id=NEW.financial_record_id
                  ),-1) != NEW.company_id)
            BEGIN
              SELECT RAISE(ABORT,'Baixa financeira fora da empresa ou direção incompatível');
            END;
            CREATE TRIGGER IF NOT EXISTS trg_financial_settlement_immutable_update
            BEFORE UPDATE ON financial_settlements BEGIN
              SELECT RAISE(ABORT,'Baixa financeira é imutável');
            END;
            CREATE TRIGGER IF NOT EXISTS trg_financial_settlement_immutable_delete
            BEFORE DELETE ON financial_settlements BEGIN
              SELECT RAISE(ABORT,'Baixa financeira é imutável');
            END;
            """
        )
        settlement_columns = {
            row["name"] for row in db.execute("PRAGMA table_info(financial_settlements)").fetchall()
        }
        if "bank_account_id" not in settlement_columns:
            db.execute("ALTER TABLE financial_settlements ADD COLUMN bank_account_id INTEGER REFERENCES bank_accounts(id)")
        legacy = db.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name='financial_settlements_legacy_237'"
        ).fetchone()
        if legacy:
            db.execute(
                """INSERT OR IGNORE INTO financial_settlements
                   (id,company_id,financial_record_id,cash_record_id,entry_type,direction,
                    principal_cents,discount_cents,interest_cents,fee_cents,cash_amount_cents,
                    settled_at,account,payment_method,note,created_by,created_at)
                   SELECT l.id,l.company_id,l.financial_record_id,l.cash_record_id,'SETTLEMENT',
                          l.direction,l.amount_cents,0,0,0,l.amount_cents,l.settled_at,
                          COALESCE(json_extract(r.payload,'$.conta'),'Caixa operacional'),
                          COALESCE(json_extract(r.payload,'$.forma_pagamento'),'Não informada'),
                          'Migrado do ledger integral v237',l.created_by,l.created_at
                     FROM financial_settlements_legacy_237 l
                     JOIN records r ON r.id=l.cash_record_id"""
            )
            db.execute("DROP TABLE financial_settlements_legacy_237")

    def ensure_company_structure(self, company_id, company_name, company_cnpj=None, now=None):
        """Garante a hierarquia mínima Company -> Branch -> Warehouse de forma idempotente."""
        db = self.connection()
        now = now or utc_now()
        branch = db.execute(
            "SELECT id FROM branches WHERE company_id=? ORDER BY is_headquarters DESC,id LIMIT 1",
            (company_id,),
        ).fetchone()
        if branch:
            branch_id = branch["id"]
        else:
            branch_id = db.execute(
                """INSERT INTO branches
                   (company_id,code,name,cnpj,active,is_headquarters,created_at,updated_at)
                   VALUES(?,'MATRIZ',?,?,1,1,?,?)""",
                (company_id, f"Matriz — {company_name}", company_cnpj, now, now),
            ).lastrowid
        warehouse = db.execute(
            "SELECT id FROM warehouses WHERE company_id=? ORDER BY id LIMIT 1",
            (company_id,),
        ).fetchone()
        if not warehouse:
            db.execute(
                """INSERT INTO warehouses
                   (company_id,branch_id,code,name,location,active,created_at,updated_at)
                   VALUES(?,?,'PRINCIPAL','Depósito principal','Matriz',1,?,?)""",
                (company_id, branch_id, now, now),
            )
        for name, category, body in (
            ("Saudação inicial", "COMERCIAL",
             "Olá, {{nome}}! Sou {{vendedor}} da SECCOL. Recebemos seu contato e gostaria de entender melhor como podemos ajudar."),
            ("Acompanhamento de proposta", "COMERCIAL",
             "Olá, {{nome}}! Passando para acompanhar a proposta {{referencia}}. Posso esclarecer algum ponto?"),
            ("Encaminhamento ao financeiro", "FINANCEIRO",
             "Olá, {{nome}}! Encaminhei sua solicitação ao nosso financeiro. A equipe responsável dará continuidade por este canal."),
        ):
            db.execute(
                """INSERT OR IGNORE INTO whatsapp_quick_replies
                   (company_id,name,category,body,active,created_by,created_at,updated_at)
                   VALUES(?,?,?,?,1,NULL,?,?)""",
                (company_id, name, category, body, now, now),
            )
        self.commit_if_outer()

    @staticmethod
    def normalize_subject(value):
        text = unicodedata.normalize("NFD", str(value or "").strip().lower())
        return "".join(char for char in text if unicodedata.category(char) != "Mn")

    @classmethod
    def normalize_financial_category(cls, value):
        return re.sub(r"\s+", " ", cls.normalize_subject(value)).strip()

    @staticmethod
    def financial_category_kind(module, payload):
        if module == "contas_pagar":
            return "EXPENSE"
        if module == "contas_receber":
            return "INCOME"
        if module == "financeiro":
            return {"Receita": "INCOME", "Despesa": "EXPENSE"}.get(
                str(payload.get("tipo_lancamento") or "").strip()
            )
        if module == "caixa":
            return {"Entrada": "INCOME", "Saída": "EXPENSE"}.get(
                str(payload.get("tipo_movimento") or "").strip()
            )
        return None

    def ensure_financial_category(self, company_id, name, kind, user_id=None, now=None):
        name = re.sub(r"\s+", " ", str(name or "").strip())[:80]
        normalized = self.normalize_financial_category(name)
        if not normalized or kind not in {"EXPENSE", "INCOME", "BOTH"}:
            return None
        now = now or utc_now()
        db = self.connection()
        db.execute(
            """INSERT OR IGNORE INTO financial_categories
               (company_id,name,normalized_name,kind,active,created_by,updated_by,created_at,updated_at)
               VALUES(?,?,?,?,1,?,?,?,?)""",
            (company_id, name, normalized, kind, user_id, user_id, now, now),
        )
        row = db.execute(
            """SELECT id,name,kind FROM financial_categories
               WHERE company_id=? AND normalized_name=?""",
            (company_id, normalized),
        ).fetchone()
        if row and row["kind"] != kind and row["kind"] != "BOTH" and kind != "BOTH":
            db.execute(
                """UPDATE financial_categories SET kind='BOTH',updated_by=?,updated_at=?
                   WHERE id=? AND company_id=?""",
                (user_id, now, row["id"], company_id),
            )
        elif row and kind == "BOTH" and row["kind"] != "BOTH":
            db.execute(
                """UPDATE financial_categories SET kind='BOTH',updated_by=?,updated_at=?
                   WHERE id=? AND company_id=?""",
                (user_id, now, row["id"], company_id),
            )
        return row["id"] if row else None

    def seed_financial_categories(self, company_id, now=None):
        for name, kind in FINANCIAL_CATEGORY_DEFAULTS:
            self.ensure_financial_category(company_id, name, kind, now=now)

    def migrate_financial_categories(self):
        """Materializa categorias legadas sem romper o histórico financeiro."""
        db = self.connection()
        rows = db.execute(
            """SELECT id,company_id,module,payload FROM records
               WHERE module IN ('contas_pagar','contas_receber','financeiro','caixa')"""
        ).fetchall()
        for row in rows:
            try:
                payload = json.loads(row["payload"] or "{}")
            except (TypeError, ValueError, json.JSONDecodeError):
                continue
            category_name = str(payload.get("categoria") or "").strip()
            kind = self.financial_category_kind(row["module"], payload)
            try:
                category_id = int(payload.get("categoria_id"))
            except (TypeError, ValueError):
                category_id = 0
            current_category = db.execute(
                """SELECT id,name FROM financial_categories
                   WHERE id=? AND company_id=?""",
                (category_id, row["company_id"]),
            ).fetchone() if category_id > 0 else None
            if current_category:
                if payload.get("categoria") != current_category["name"]:
                    payload["categoria"] = current_category["name"]
                    db.execute(
                        "UPDATE records SET payload=? WHERE id=? AND company_id=?",
                        (json_dumps(payload), row["id"], row["company_id"]),
                    )
                continue
            if not category_name or not kind:
                continue
            category_id = self.ensure_financial_category(
                row["company_id"], category_name, kind,
            )
            category = db.execute(
                """SELECT id,name FROM financial_categories
                   WHERE id=? AND company_id=?""",
                (category_id, row["company_id"]),
            ).fetchone()
            if category and (payload.get("categoria_id") != category["id"] or
                             payload.get("categoria") != category["name"]):
                payload["categoria_id"] = category["id"]
                payload["categoria"] = category["name"]
                db.execute(
                    "UPDATE records SET payload=? WHERE id=? AND company_id=?",
                    (json_dumps(payload), row["id"], row["company_id"]),
                )

    def ensure_subject(self, name, user_id=None, company_id=None):
        name = str(name or "").strip()[:180]
        company_id = int(company_id or 1)
        normalized = self.normalize_subject(name)
        if not normalized:
            return None
        normalized_key = f"{company_id}:{normalized}"
        now = utc_now()
        self.connection().execute(
            """INSERT OR IGNORE INTO subjects
               (name,normalized_name,status,created_by,created_at,updated_at,company_id)
               VALUES(?,?,'Ativo',?,?,?,?)""",
            (name, normalized_key, user_id, now, now, company_id))
        row = self.connection().execute(
            "SELECT id FROM subjects WHERE company_id=? AND normalized_name=?",
            (company_id, normalized_key)).fetchone()
        return row["id"] if row else None

    def sync_relationships(self, record_id, payload, user_id=None, company_id=None):
        db = self.connection()
        record = db.execute("SELECT company_id FROM records WHERE id=?", (record_id,)).fetchone()
        company_id = int(company_id or (record["company_id"] if record else 1) or 1)
        subject_id = self.ensure_subject(payload.get("assunto"), user_id, company_id)
        db.execute("UPDATE records SET subject_id=? WHERE id=?", (subject_id, record_id))
        db.execute("DELETE FROM record_subjects WHERE record_id=?", (record_id,))
        if subject_id:
            db.execute(
                """INSERT OR IGNORE INTO record_subjects
                   (record_id,subject_id,relationship_type,is_primary,created_by,created_at)
                   VALUES(?,?,'Assunto principal',1,?,?)""",
                (record_id, subject_id, user_id, utc_now()))
        additional_subjects = payload.get("assuntos_adicionais") or []
        if isinstance(additional_subjects, str):
            additional_subjects = [item.strip() for item in additional_subjects.split(",") if item.strip()]
        if isinstance(additional_subjects, list):
            for additional_name in additional_subjects[:30]:
                additional_id = self.ensure_subject(additional_name, user_id, company_id)
                if additional_id and additional_id != subject_id:
                    db.execute(
                        """INSERT OR IGNORE INTO record_subjects
                           (record_id,subject_id,relationship_type,is_primary,created_by,created_at)
                           VALUES(?,?,'Relacionado a',0,?,?)""",
                        (record_id, additional_id, user_id, utc_now()))
        requested = []
        primary = str(payload.get("registro_relacionado") or "").strip()
        if primary:
            requested.append({"record": primary, "type": payload.get("tipo_relacao") or "Relacionado a"})
        if isinstance(payload.get("relacionamentos"), list):
            requested.extend(payload["relacionamentos"][:50])
        db.execute("DELETE FROM record_relationships WHERE from_record_id=?", (record_id,))
        for relation in requested:
            if not isinstance(relation, dict):
                continue
            reference = str(relation.get("record") or relation.get("registro") or "")
            match = re.fullmatch(r"([a-z_]+):(\d+)", reference)
            if not match or match.group(1) not in MODULES:
                raise ValueError("Referência de relacionamento inválida")
            target_module, target_id = match.group(1), int(match.group(2))
            if target_id == record_id:
                raise ValueError("Um registro não pode ser relacionado a ele próprio")
            exists = db.execute(
                """SELECT id FROM records
                   WHERE id=? AND module=? AND company_id=? AND deleted_at IS NULL""",
                (target_id, target_module, company_id)).fetchone()
            if not exists:
                raise ValueError(
                    "O registro relacionado não existe, pertence a outro módulo/empresa ou foi excluído"
                )
            relation_type = str(relation.get("type") or relation.get("tipo") or "Relacionado a").strip()[:80]
            db.execute(
                """INSERT OR IGNORE INTO record_relationships
                   (from_record_id,to_record_id,relationship_type,created_by,created_at) VALUES(?,?,?,?,?)""",
                (record_id, target_id, relation_type, user_id, utc_now()))
    def migrate_subjects(self):
        db = self.connection()
        rows = db.execute("SELECT id,payload,created_by,company_id FROM records WHERE subject_id IS NULL").fetchall()
        for row in rows:
            try:
                payload = json.loads(row["payload"] or "{}")
                if payload.get("assunto"):
                    self.sync_relationships(row["id"], payload, row["created_by"], row["company_id"])
            except (ValueError, TypeError, json.JSONDecodeError):
                continue

    def migrate_record_references(self):
        """Recupera vínculos antigos quando o nome identifica um único cadastro mestre."""
        db = self.connection()
        rows = db.execute(
            """SELECT id,module,payload,company_id,created_by FROM records
               WHERE deleted_at IS NULL AND module NOT IN ('clientes','fornecedores')"""
        ).fetchall()
        for row in rows:
            try:
                payload = json.loads(row["payload"] or "{}")
            except (ValueError, TypeError, json.JSONDecodeError):
                continue
            changed = False
            new_relations = []
            for field, rule in RECORD_REFERENCE_RULES.items():
                id_key = f"{field}_id"
                display = str(payload.get(field) or "").strip()
                if payload.get(id_key) or not display:
                    continue
                placeholders = ",".join("?" for _ in rule["modules"])
                candidates = db.execute(
                    f"""SELECT id,module,title,payload FROM records
                        WHERE company_id=? AND deleted_at IS NULL
                          AND module IN ({placeholders}) AND title=? COLLATE NOCASE LIMIT 3""",
                    (row["company_id"], *rule["modules"], display),
                ).fetchall()
                expected_role = rule.get("party_role")
                if expected_role:
                    compatible = []
                    for candidate in candidates:
                        candidate_payload = json.loads(candidate["payload"] or "{}")
                        fallback = "F" if candidate["module"] == "fornecedores" else "C"
                        role = str(candidate_payload.get("tipo_cadastro") or fallback).strip()
                        role = {"Cliente (C)": "C", "Fornecedor (F)": "F",
                                "Cliente e fornecedor (A)": "A", "C e F": "A"}.get(role, role)
                        if expected_role == "A" or role == "A" or role == expected_role:
                            compatible.append(candidate)
                    candidates = compatible
                if len(candidates) != 1:
                    continue
                target = candidates[0]
                payload[id_key] = target["id"]
                payload[field] = target["title"]
                new_relations.append((target["id"], rule["relation"]))
                changed = True
            if not changed:
                continue
            db.execute("UPDATE records SET payload=? WHERE id=?", (json_dumps(payload), row["id"]))
            for target_id, relation_type in new_relations:
                db.execute(
                    """INSERT OR IGNORE INTO record_relationships
                       (from_record_id,to_record_id,relationship_type,created_by,created_at)
                       VALUES(?,?,?,?,?)""",
                    (row["id"], target_id, relation_type, row["created_by"], utc_now()),
                )
        self.commit_if_outer()

    def seed_sources(self, company_id=None):
        db = self.connection()
        now = utc_now()
        company_ids = [company_id] if company_id else [row["id"] for row in db.execute(
            "SELECT id FROM companies WHERE active=1").fetchall()]
        for current_company_id in company_ids:
            for key, name, url, coverage, collection_mode, category in SOURCE_CATALOG:
                exists = db.execute(
                    """SELECT id,title,payload FROM records WHERE company_id=? AND module='fontes'
                       AND json_extract(payload,'$.source_key')=?""",
                    (current_company_id, key),
                ).fetchone()
                if exists:
                    try:
                        payload = json.loads(exists["payload"] or "{}")
                    except json.JSONDecodeError:
                        payload = {}
                    payload.update({
                        "source_key": key, "url": url, "abrangencia": coverage,
                        "modo_coleta": collection_mode, "categoria": category,
                        "verificado_em": "2026-08-15",
                        "assunto": f"Fonte de busca — {name}",
                    })
                    if not payload.get("palavra_chave"):
                        payload["palavra_chave"] = ", ".join(DEFAULT_TENDER_KEYWORDS)
                    encoded_payload = json_dumps(payload)
                    if exists["title"] != name or exists["payload"] != encoded_payload:
                        db.execute(
                            "UPDATE records SET title=?,payload=?,updated_at=? WHERE id=?",
                            (name, encoded_payload, now, exists["id"]),
                        )
                    self.sync_relationships(exists["id"], payload, None, current_company_id)
                    continue
                payload = {
                    "source_key": key, "url": url, "abrangencia": coverage,
                    "modo_coleta": collection_mode, "categoria": category,
                    "palavra_chave": ", ".join(DEFAULT_TENDER_KEYWORDS),
                    "verificado_em": "2026-08-15", "ativo": True,
                    "ultima_execucao": None, "ultimo_sucesso": None,
                    "assunto": f"Fonte de busca — {name}",
                }
                cursor = db.execute(
                    """INSERT INTO records
                       (module,title,status,payload,company_id,created_at,updated_at)
                       VALUES('fontes',?,'Ativo',?,?,?,?)""",
                    (name, json_dumps(payload), current_company_id, now, now),
                )
                self.sync_relationships(cursor.lastrowid, payload, None, current_company_id)
        self.commit_if_outer()

